import { Diagram } from '../Diagram';

/**
 * Chapter2 セクションコンポーネント
 */
export default function Chapter2() {
    return (
        <>
<section className={"sec ch"} id={"第2章-コア試験-350-401-encor"}>{"\n                    "}<h2 id={"第2章-コア試験-350-401-encor"}>{"第2章 コア試験 350-401 ENCOR"}</h2>{"\n                "}</section>
<section className={"sec sub"} id={"出題配分試験内容-pdf-v12-準拠"}>{"\n                    "}<h3 id={"出題配分試験内容-pdf-v12-準拠"}>{"出題配分（試験内容 PDF v1.2 準拠）"}</h3>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"出題配分（試験内容 PDF v1.2 準拠）（表 5）"}><thead><tr><th scope="col">{"#"}{" "}</th><th scope="col">{"ドメイン"}{" "}</th><th scope="col">{"配分"}{" "}</th></tr></thead><tbody><tr><td>{"1.0"}{" "}</td><td>{"アーキテクチャ"}{" "}</td><td>{"15%"}{" "}</td></tr><tr><td>{"2.0"}{" "}</td><td>{"仮想化"}{" "}</td><td>{"10%"}{" "}</td></tr><tr><td>{"3.0"}{" "}</td><td>{"インフラストラクチャ"}{" "}</td><td><strong>{"30%"}</strong>{" "}</td></tr><tr><td>{"4.0"}{" "}</td><td>{"ネットワークアシュアランス"}{" "}</td><td>{"10%"}{" "}</td></tr><tr><td>{"5.0"}{" "}</td><td>{"セキュリティ"}{" "}</td><td>{"20%"}{" "}</td></tr><tr><td>{"6.0"}{" "}</td><td>{"自動化と人工知能"}{" "}</td><td>{"15%"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<Diagram id="dg3" label={"出題配分（試験内容 PDF v1.2 準拠）"} />{"\n                    "}<aside className={"callout note"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-info-circle"}></i><span>{"補足"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                各節の設定例は\n                                "}<strong>{"IOS XE"}</strong>{" を前提にした学習用の最小構成です。IP\n                                アドレスは文書用のもの（192.0.2.0/24\n                                などの例示用範囲）を使っています。本番投入前に必ず自環境のバージョン・要件で検証してください。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                "}</section>
<section className={"sec sub"} id={"21-アーキテクチャ15"}>{"\n                    "}<h3 id={"21-アーキテクチャ15"}>{"2.1 アーキテクチャ（15%）"}</h3>{"\n                    "}<h4 id={"11-エンタープライズネットワークの設計原則"}>{"\n                        1.1 エンタープライズ・ネットワークの設計原則\n                    "}</h4>{"\n                    "}<p>{"\n                        "}<strong>{"なぜ必要か"}</strong>{":\n                        ネットワークは「増設のたびに複雑化する」のが宿命です。設計原則（階層化・モジュール化・回復性・柔軟性）を決めておくと、障害範囲の限定・拡張・運用の単純化ができます。\n                    "}</p>{"\n                    "}<h5 id={"11a-ハイレベル設計2-階層3-階層ファブリッククラウド"}>{"\n                        1.1.a ハイレベル設計（2 階層、3 階層、ファブリック、クラウド）\n                    "}</h5>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"1.1 エンタープライズ・ネットワークの設計原則（表 6）"}><thead><tr><th scope="col">{"モデル"}{" "}</th><th scope="col">{"構成"}{" "}</th><th scope="col">{"向いている規模"}{" "}</th><th scope="col">{"特徴"}{" "}</th></tr></thead><tbody><tr><td>{"3 階層"}{" "}</td><td>{"アクセス／ディストリビューション／コア"}{" "}</td><td>{"大規模キャンパス（複数の機能ブロックを相互接続）"}{" "}</td><td>{"拡張性・障害分離に優れる。機器数とコストが増える"}{" "}</td></tr><tr><td>{"2 階層（コラプストコア）"}{" "}</td><td>{"アクセス／コラプスト（コア＋ディストリビューション）"}{" "}</td><td>{"\n                                        小〜中規模（Cisco Press\n                                        の記述では、相互接続する機能ブロックは 3 つ程度までが目安）\n                                    "}{" "}</td><td>{"コスト削減しつつ階層化のメリットを維持"}{" "}</td></tr><tr><td>{"ファブリック"}{" "}</td><td>{"アンダーレイ＋オーバーレイ（例: SD-Access）"}{" "}</td><td>{"自動化・セグメンテーションを重視するキャンパス"}{" "}</td><td>{"論理ネットワークを Catalyst Center で一元管理"}{" "}</td></tr><tr><td>{"クラウド"}{" "}</td><td>{"クラウド上の VPC/VNet＋接続基盤（SD-WAN、専用線）"}{" "}</td><td>{"ハイブリッド／マルチクラウド"}{" "}</td><td>{"接続・ポリシーの一貫性が課題"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<p>{"各階層の役割は次のとおりです（Cisco Press の解説に基づく）。"}</p>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"1.1 エンタープライズ・ネットワークの設計原則（表 7）"}><thead><tr><th scope="col">{"階層"}{" "}</th><th scope="col">{"役割"}{" "}</th></tr></thead><tbody><tr><td>{"コア"}{" "}</td><td>{"\n                                        サイト間の最適な転送と高性能ルーティング。障害後に素早く滑らかに回復する回復性が必須\n                                    "}{" "}</td></tr><tr><td>{"ディストリビューション"}{" "}</td><td>{"\n                                        アクセスとコアの間で、"}<strong>{"ポリシーベースの接続と境界制御"}</strong>{"を提供\n                                    "}{" "}</td></tr><tr><td>{"アクセス"}{" "}</td><td>{"ユーザー／ワークグループのネットワーク接続を提供"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<Diagram id="dg4" label={"1.1 エンタープライズ・ネットワークの設計原則"} />{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<ol>{"\n                                "}<li>{"\n                                    "}<strong>{"全階層でリンクとノードを二重化"}</strong>{"し、単一障害点（SPOF）を作らない。\n                                "}</li>{"\n                                "}<li>{"\n                                    ディストリビューション間はレイヤ 3 で接続し、"}<strong>{"L2 ドメインを小さく"}</strong>{"保つ（ブロードキャスト／STP の影響範囲を限定）。\n                                "}</li>{"\n                                "}<li>{"\n                                    "}<strong>{"ルーテッドアクセス"}</strong>{"（アクセス層まで\n                                    L3）を検討し、STP 依存を減らして収束を高速化する。\n                                "}</li>{"\n                                "}<li>{"\n                                    ルート集約と各種ポリシーは"}<strong>{"ディストリビューション境界"}</strong>{"に集約する。\n                                "}</li>{"\n                                "}<li>{"\n                                    小規模なら 2\n                                    階層で始め、機能ブロックが増えたらコアを分離する（"}<strong>{"成長に合わせて拡張できる設計"}</strong>{"）。\n                                "}</li>{"\n                            "}</ol>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<aside className={"callout note"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-info-circle"}></i><span>{"よくある落とし穴"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                「全 VLAN をキャンパス全体に伸ばす」設計は、障害時の影響範囲が広がり\n                                STP 収束も遅くなります。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h5 id={"11b-高可用性技術冗長性fhrpsso"}>{"\n                        1.1.b 高可用性技術（冗長性、FHRP、SSO）\n                    "}</h5>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"1.1 エンタープライズ・ネットワークの設計原則（表 8）"}><thead><tr><th scope="col">{"技術"}{" "}</th><th scope="col">{"何を守る？"}{" "}</th><th scope="col">{"ポイント"}{" "}</th></tr></thead><tbody><tr><td>{"物理冗長（二重化リンク／機器）"}{" "}</td><td>{"リンク・機器故障"}{" "}</td><td>{"異なる筐体／異なる経路に分散させる"}{" "}</td></tr><tr><td>{"EtherChannel"}{" "}</td><td>{"リンク故障・帯域"}{" "}</td><td>{"複数リンクを 1 本の論理リンクに束ねる"}{" "}</td></tr><tr><td>{"FHRP（HSRP/VRRP/GLBP）"}{" "}</td><td>{"デフォルトゲートウェイ故障"}{" "}</td><td>{"仮想 IP をゲートウェイとして共有（詳細は 3.3.c）"}{" "}</td></tr><tr><td>{"SSO（Stateful Switchover）"}{" "}</td><td>{"スーパバイザ／スタック故障"}{" "}</td><td>{"\n                                        スタンバイがコンフィグと状態を同期し、切替時の停止を最小化\n                                    "}{" "}</td></tr><tr><td>{"NSF / グレースフルリスタート"}{" "}</td><td>{"制御プレーン再起動時の転送断"}{" "}</td><td>{"制御プレーン復旧中もデータ転送を継続"}{" "}</td></tr><tr><td>{"BFD"}{" "}</td><td>{"障害検知の遅さ"}{" "}</td><td>{"\n                                        ミリ秒〜秒単位で高速検知し、ルーティングプロトコルに通知\n                                    "}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<Diagram id="dg5" label={"1.1 エンタープライズ・ネットワークの設計原則"} />{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<ul>{"\n                                "}<li>{"\n                                    冗長化は「"}<strong>{"二重化したら、切替が実際に動くことをテストする"}</strong>{"」までが設計。定期的に障害試験を行う。\n                                "}</li>{"\n                                "}<li>{"\n                                    FHRP のアクティブ側と STP\n                                    ルートブリッジ・ルーティングの最適経路を"}<strong>{"揃える"}</strong>{"（非対称経路や余計な迂回を避ける）。\n                                "}</li>{"\n                                "}<li>{"\n                                    ソフトウェアアップグレード計画には SSO/NSF の対応可否を含める。\n                                "}</li>{"\n                            "}</ul>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<aside className={"callout note"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-info-circle"}></i><span>{"理解チェック"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                「FHRP と SSO はそれぞれ何の障害から守る？」→ FHRP\n                                はゲートウェイ（L3 の到達性）、SSO\n                                は機器内部の制御部（スーパバイザ等）の障害です。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h4 id={"12-cisco-catalyst-sd-wan-の動作原理"}>{"\n                        1.2 Cisco Catalyst SD-WAN の動作原理\n                    "}</h4>{"\n                    "}<p>{"\n                        "}<strong>{"なぜ必要か"}</strong>{": 従来の WAN は MPLS\n                        中心で、帯域コストが高く、SaaS\n                        利用時に中央へ折り返す（バックホール）非効率がありました。SD-WAN\n                        は"}<strong>{"制御を集中、転送を分散"}</strong>{"し、複数回線を活用して品質・コスト・運用を改善します。\n                    "}</p>{"\n                    "}<h5 id={"12a-コントロールプレーンとデータプレーンの要素"}>{"\n                        1.2.a コントロールプレーンとデータプレーンの要素\n                    "}</h5>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"1.2 Cisco Catalyst SD-WAN の動作原理（表 9）"}><thead><tr><th scope="col">{"プレーン"}{" "}</th><th scope="col">{"コンポーネント（旧称）"}{" "}</th><th scope="col">{"役割"}{" "}</th></tr></thead><tbody><tr><td>{"オーケストレーション"}{" "}</td><td>{"SD-WAN Validator（vBond）"}{" "}</td><td>{"初期認証、コンポーネントの発見、NAT 越え支援"}{" "}</td></tr><tr><td>{"管理"}{" "}</td><td>{"SD-WAN Manager（vManage）"}{" "}</td><td>{"一元管理 GUI／API、ポリシー・テンプレート作成、監視"}{" "}</td></tr><tr><td>{"コントロール"}{" "}</td><td>{"SD-WAN Controller（vSmart）"}{" "}</td><td><strong>{"OMP"}</strong>{" でルート・ポリシーを配布"}{" "}</td></tr><tr><td>{"データ"}{" "}</td><td>{"WAN Edge（ルータ）"}{" "}</td><td>{"ユーザートラフィック転送、IPsec/GRE トンネル、BFD"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<ul>{"\n                        "}<li>{"\n                            "}<strong>{"OMP（Overlay Management Protocol）"}</strong>{": コントローラと WAN\n                            Edge 間でルート、TLOC、サービス情報、ポリシーを交換するプロトコル。\n                        "}</li>{"\n                        "}<li>{"\n                            "}<strong>{"TLOC（Transport Locator）"}</strong>{":\n                            オーバーレイのトンネル終端を表す識別子。"}<strong>{"システム IP・カラー・カプセル化方式"}</strong>{"の組で識別される。\n                        "}</li>{"\n                        "}<li>{"\n                            "}<strong>{"vRoute（OMP ルート）"}</strong>{":\n                            VPN（セグメント）に属し、ネクストホップは IP ではなく\n                            "}<strong>{"TLOC"}</strong>{"。\n                        "}</li>{"\n                        "}<li>{"\n                            "}<strong>{"BFD"}</strong>{": 各 IPsec\n                            トンネル上で自動的に動作し、トンネル品質（遅延・ロス・ジッタ）を計測する。\n                        "}</li>{"\n                    "}</ul>{"\n                    "}<Diagram id="dg6" label={"1.2 Cisco Catalyst SD-WAN の動作原理"} />{"\n                    "}<h5 id={"12b-利点と制約"}>{"1.2.b 利点と制約"}</h5>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"1.2 Cisco Catalyst SD-WAN の動作原理（表 10）"}><thead><tr><th scope="col">{"区分"}{" "}</th><th scope="col">{"内容"}{" "}</th></tr></thead><tbody><tr><td>{"利点"}{" "}</td><td>{"\n                                        集中管理・ポリシー一元化／MPLS＋ブロードバンド等を"}<strong>{"アクティブ/アクティブ"}</strong>{"で活用／トランスポート非依存のオーバーレイ／制御とデータの分離による展開の柔軟性（コントローラはオンプレ・クラウド可）／暗号化・セグメンテーション・証明書ベースのゼロトラスト的認証／アプリケーション可視化とアプリ認識型ポリシー\n                                    "}{" "}</td></tr><tr><td>{"考慮点（制約）"}{" "}</td><td>{"\n                                        コントローラ構成・証明書・デバイスリストの"}<strong>{"運用設計が必要"}</strong>{"／アンダーレイ（回線）品質と\n                                        NAT\n                                        構成の影響を受ける／ファイアウォールで制御接続用ポートの許可が必要／導入プロジェクトとして既存\n                                        WAN からの移行計画が必要\n                                    "}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                制御コンポーネントは冗長化し、証明書の有効期限管理を運用に組み込む。拠点は「1\n                                拠点 = 1 サイト ID」を厳密に設計する（サイト ID は OMP\n                                のループ防止にも使われる）。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h4 id={"13-cisco-sd-access-の動作原理"}>{"1.3 Cisco SD-Access の動作原理"}</h4>{"\n                    "}<p>{"\n                        "}<strong>{"なぜ必要か"}</strong>{": 従来キャンパスは VLAN と ACL\n                        の手作業が中心で、変更が遅くミスも起こりやすい状態でした。SD-Access\n                        は"}<strong>{"意図（インテント）をポリシーとして定義し、Catalyst Center\n                            が自動展開"}</strong>{"します。\n                    "}</p>{"\n                    "}<h5 id={"13a-コントロールプレーンとデータプレーンの要素"}>{"\n                        1.3.a コントロールプレーンとデータプレーンの要素\n                    "}</h5>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"1.3 Cisco SD-Access の動作原理（表 11）"}><thead><tr><th scope="col">{"要素"}{" "}</th><th scope="col">{"技術・役割"}{" "}</th></tr></thead><tbody><tr><td>{"アンダーレイ"}{" "}</td><td>{"物理 IP ネットワーク（ルーテッドで高速収束）"}{" "}</td></tr><tr><td>{"オーバーレイ"}{" "}</td><td>{"\n                                        仮想ネットワーク（VN）。"}<strong>{"VXLAN"}</strong>{"\n                                        でカプセル化（SGT 情報を運べる）\n                                    "}{" "}</td></tr><tr><td>{"コントロールプレーン"}{" "}</td><td>{"\n                                        "}<strong>{"LISP"}</strong>{"（EID と RLOC\n                                        のマッピングを管理）。ファブリックの「電話帳」\n                                    "}{" "}</td></tr><tr><td>{"ポリシープレーン"}{" "}</td><td>{"\n                                        "}<strong>{"Cisco TrustSec"}</strong>{"（SGT）と ISE\n                                        による識別ベースのアクセス制御\n                                    "}{" "}</td></tr><tr><td>{"管理プレーン"}{" "}</td><td>{"\n                                        "}<strong>{"Cisco Catalyst Center"}</strong>{"（設計・自動化・アシュアランス）\n                                    "}{" "}</td></tr><tr><td>{"ノードの役割"}{" "}</td><td>{"\n                                        エッジノード（端末収容）／ボーダーノード（外部接続）／コントロールプレーンノード\n                                    "}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<Diagram id="dg7" label={"1.3 Cisco SD-Access の動作原理"} />{"\n                    "}<ul>{"\n                        "}<li>{"\n                            "}<strong>{"マクロセグメンテーション"}</strong>{": VN（VRF 相当）で大きく分離。\n                        "}</li>{"\n                        "}<li>{"\n                            "}<strong>{"マイクロセグメンテーション"}</strong>{": VN 内で\n                            "}<strong>{"SGT（Security Group Tag）"}</strong>{" によりグループ間通信を制御。\n                        "}</li>{"\n                    "}</ul>{"\n                    "}<h5 id={"13b-sd-access-と相互運用する従来型キャンパス"}>{"\n                        1.3.b SD-Access と相互運用する従来型キャンパス\n                    "}</h5>{"\n                    "}<p>{"\n                        移行期には、既存（従来型）キャンパスとファブリックが共存します。ボーダーノードで外部ネットワークと接続し、段階的に移行します。\n                    "}</p>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<ol>{"\n                                "}<li>{"\n                                    アンダーレイは"}<strong>{"ルーテッド"}</strong>{"で設計し、Catalyst\n                                    Center による LAN オートメーションの利用を検討する。\n                                "}</li>{"\n                                "}<li>{"\n                                    VN の数は必要最小限に。まず"}<strong>{"マクロ（VN）→ 次にマイクロ（SGT）"}</strong>{"の順で設計する。\n                                "}</li>{"\n                                "}<li>{"\n                                    既存環境からは"}<strong>{"段階移行"}</strong>{"し、ボーダーでの接続（ルーティング、セグメントのマッピング）を明文化する。\n                                "}</li>{"\n                                "}<li>{"\n                                    スケール値やレイテンシ要件は"}<strong>{"最新の Catalyst Center データシートと設計ガイド"}</strong>{"で確認する。\n                                "}</li>{"\n                            "}</ol>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h4 id={"14-qos-の理解"}>{"1.4 QoS の理解"}</h4>{"\n                    "}<p>{"\n                        "}<strong>{"なぜ必要か"}</strong>{":\n                        回線が混雑したとき、音声・ビデオ・業務アプリを優先し、ベストエフォートの通信を後回しにするためです。\n                    "}</p>{"\n                    "}<Diagram id="dg8" label={"1.4 QoS の理解"} />{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"1.4 QoS の理解（表 12）"}><thead><tr><th scope="col">{"機能"}{" "}</th><th scope="col">{"内容"}{" "}</th></tr></thead><tbody><tr><td>{"分類"}{" "}</td><td>{"\n                                        トラフィックを種類ごとに識別（ACL、DSCP\n                                        値、アプリケーション認識）\n                                    "}{" "}</td></tr><tr><td>{"マーキング"}{" "}</td><td>{"\n                                        パケットに優先度を記録（L3 は "}<strong>{"DSCP"}</strong>{"、L2 は\n                                        "}<strong>{"CoS"}</strong>{"）\n                                    "}{" "}</td></tr><tr><td>{"ポリシング"}{" "}</td><td>{"\n                                        制限を超えた分を"}<strong>{"破棄またはリマーク"}</strong>{"（バースト後の遅延は生まない）\n                                    "}{" "}</td></tr><tr><td>{"シェーピング"}{" "}</td><td>{"\n                                        超過分を"}<strong>{"バッファして遅らせる"}</strong>{"（送信を平滑化）\n                                    "}{" "}</td></tr><tr><td>{"キューイング"}{" "}</td><td>{"\n                                        優先クラスを先に送る（"}<strong>{"LLQ"}</strong>{"＝厳格優先、"}<strong>{"CBWFQ"}</strong>{"＝帯域保証）\n                                    "}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<p>{"代表的な DSCP 値:"}</p>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"1.4 QoS の理解（表 13）"}><thead><tr><th scope="col">{"トラフィック"}{" "}</th><th scope="col">{"代表的な DSCP"}{" "}</th></tr></thead><tbody><tr><td>{"音声（Voice）"}{" "}</td><td>{"EF（46）"}{" "}</td></tr><tr><td>{"ビデオ会議"}{" "}</td><td>{"AF41（34）"}{" "}</td></tr><tr><td>{"シグナリング"}{" "}</td><td>{"CS3（24）"}{" "}</td></tr><tr><td>{"既定（ベストエフォート）"}{" "}</td><td>{"0"}{" "}</td></tr><tr><td>{"スカベンジャー（低優先）"}{" "}</td><td>{"CS1（8）"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<p><strong>{"設定例（MQC）"}</strong></p>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"class-map"}</span>{" match-any VOICE"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"match"}</span>{" dscp ef"}</div><div className="code-line"><span className={"t-kw"}>{"class-map"}</span>{" match-any VIDEO"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"match"}</span>{" dscp af41"}</div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"policy-map"}</span>{" WAN-EDGE-OUT"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"class"}</span>{" VOICE"}</div><div className="code-line">{"  "}<span className={"t-sub"}>{"priority"}</span>{" percent 10"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"class"}</span>{" VIDEO"}</div><div className="code-line">{"  "}<span className={"t-sub"}>{"bandwidth"}</span>{" remaining percent 30"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"class"}</span>{" class-default"}</div><div className="code-line">{"  "}<span className={"t-sub"}>{"fair-queue"}</span></div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"interface"}</span>{" GigabitEthernet0/0/0"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"service-policy"}</span>{" output WAN-EDGE-OUT"}</div></div>{"\n                    "}</div>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<ol>{"\n                                "}<li>{"\n                                    "}<strong>{"信頼境界（trust\n                                        boundary）を明確にし、できるだけエッジ（アクセス）で分類・マーキング"}</strong>{"する。\n                                "}</li>{"\n                                "}<li>{"\n                                    ネットワーク全体で"}<strong>{"マーキングの方針を統一"}</strong>{"（エンドツーエンドで一貫させる）。\n                                "}</li>{"\n                                "}<li>{"\n                                    優先キュー（LLQ）は帯域の一部に"}<strong>{"制限"}</strong>{"する（優先しすぎると他クラスが飢餓状態になる）。\n                                "}</li>{"\n                                "}<li>{"\n                                    契約帯域より低い値にシェーピングしてから、その中でキューイングする（階層型ポリシー）。\n                                "}</li>{"\n                                "}<li>{"\n                                    適用後は\n                                    "}<code>{"show policy-map interface"}</code>{"\n                                    で"}<strong>{"クラス別のカウンタとドロップを確認"}</strong>{"する。\n                                "}</li>{"\n                            "}</ol>{"\n                        "}</div>{"\n                    "}</aside>{"\n                "}</section>
<section className={"sec sub"} id={"22-仮想化10"}>{"\n                    "}<h3 id={"22-仮想化10"}>{"2.2 仮想化（10%）"}</h3>{"\n                    "}<h4 id={"21-デバイス仮想化テクノロジー"}>{"2.1 デバイス仮想化テクノロジー"}</h4>{"\n                    "}<h5 id={"21a-ハイパーバイザ-type-1--type-221b-仮想マシン"}>{"\n                        2.1.a ハイパーバイザ Type 1 / Type 2、2.1.b 仮想マシン\n                    "}</h5>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"2.1 デバイス仮想化テクノロジー（表 14）"}><thead><tr><th scope="col">{"種類"}{" "}</th><th scope="col">{"動作"}{" "}</th><th scope="col">{"例"}{" "}</th><th scope="col">{"用途"}{" "}</th></tr></thead><tbody><tr><td>{"Type 1（ベアメタル）"}{" "}</td><td>{"ハードウェア上で直接動作"}{" "}</td><td>{"VMware ESXi、KVM など"}{" "}</td><td>{"本番サーバ／ネットワーク機能の仮想化基盤"}{" "}</td></tr><tr><td>{"Type 2（ホスト型）"}{" "}</td><td>{"OS 上のアプリとして動作"}{" "}</td><td>{"VirtualBox、VMware Workstation など"}{" "}</td><td>{"学習・検証"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<ul>{"\n                        "}<li>{"\n                            "}<strong>{"仮想マシン（VM）"}</strong>{": ハイパーバイザ上で、独自の OS・仮想\n                            NIC・仮想ディスクを持つ論理サーバ。\n                        "}</li>{"\n                        "}<li>{"\n                            仮想化の利点:\n                            集約による機器コスト削減、迅速な展開、スナップショットによる検証。\n                        "}</li>{"\n                    "}</ul>{"\n                    "}<h5 id={"21c-仮想スイッチング"}>{"2.1.c 仮想スイッチング"}</h5>{"\n                    "}<p>{"\n                        "}<strong>{"仮想スイッチ（vSwitch）"}</strong>{" は、ホスト内の VM 同士と物理 NIC\n                        の間を L2 で接続するソフトウェアスイッチです。VLAN\n                        タグ付けやトランク接続で物理スイッチと連携します。\n                    "}</p>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                ホスト側の物理 NIC\n                                を"}<strong>{"複数本でチーム化"}</strong>{"し、上流スイッチ側の設定（トランク許可\n                                VLAN、EtherChannel の有無）と"}<strong>{"必ず整合"}</strong>{"させます。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h4 id={"22-データパス仮想化の設定と確認"}>{"2.2 データパス仮想化の設定と確認"}</h4>{"\n                    "}<h5 id={"22a-vrfvirtual-routing-and-forwarding"}>{"\n                        2.2.a VRF（Virtual Routing and Forwarding）\n                    "}</h5>{"\n                    "}<p>{"\n                        1\n                        台のルータ内に"}<strong>{"独立したルーティングテーブル"}</strong>{"を複数持つ技術です。顧客別・部門別の分離に使います。\n                    "}</p>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"vrf"}</span>{" definition CUST-A"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"address-family"}</span>{" ipv4"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"exit-address-family"}</span></div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"interface"}</span>{" GigabitEthernet0/0/1"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"vrf"}</span>{" forwarding CUST-A"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"ip"}</span>{" address "}<span className={"t-n"}>{"192.0.2.1"}</span>{" "}<span className={"t-n"}>{"255.255.255.0"}</span></div></div>{"\n                    "}</div>{"\n                    "}<p>{"\n                        確認コマンド: "}<code>{"show vrf"}</code>{"、"}<code>{"show ip route vrf CUST-A"}</code>{"、"}<code>{"ping vrf CUST-A 192.0.2.2"}</code>{"\n                    "}</p>{"\n                    "}<aside className={"callout note"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-info-circle"}></i><span>{"落とし穴"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                インターフェイスを VRF に入れると\n                                "}<strong>{"IP アドレスが消える"}</strong>{"ので、"}<code>{"vrf forwarding"}</code>{"\n                                の後に IP を再設定します。ping/traceroute/ルーティングプロトコルも\n                                "}<strong>{"VRF を指定"}</strong>{"する必要があります。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h5 id={"22b-gre-と-ipsec-のトンネリング"}>{"2.2.b GRE と IPsec のトンネリング"}</h5>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"2.2 データパス仮想化の設定と確認（表 15）"}><thead><tr><th scope="col">{"技術"}{" "}</th><th scope="col">{"特徴"}{" "}</th><th scope="col">{"暗号化"}{" "}</th></tr></thead><tbody><tr><td>{"GRE"}{" "}</td><td>{"\n                                        多様なプロトコルを運べる汎用トンネル。ルーティングプロトコルも通せる\n                                    "}{" "}</td><td>{"なし"}{" "}</td></tr><tr><td>{"IPsec"}{" "}</td><td>{"機密性・完全性・認証を提供"}{" "}</td><td>{"あり"}{" "}</td></tr><tr><td>{"GRE over IPsec / IPsec VTI"}{" "}</td><td>{"トンネルにルーティングを載せつつ暗号化"}{" "}</td><td>{"あり"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-cm"}>{"! GRE トンネル（暗号化なし）"}</span></div><div className="code-line"><span className={"t-kw"}>{"interface"}</span>{" Tunnel0"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"ip"}</span>{" address "}<span className={"t-n"}>{"10.255.0.1"}</span>{" "}<span className={"t-n"}>{"255.255.255.252"}</span></div><div className="code-line">{" "}<span className={"t-sub"}>{"tunnel"}</span>{" source GigabitEthernet0/0/0"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"tunnel"}</span>{" destination "}<span className={"t-n"}>{"198.51.100.2"}</span></div></div>{"\n                    "}</div>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-cm"}>{"! IPsec VTI（IKEv2）の最小例（事前共有鍵は例示。本番では証明書認証を推奨）"}</span></div><div className="code-line"><span className={"t-kw"}>{"crypto"}</span>{" ikev2 proposal PROP"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"encryption"}</span>{" aes-cbc-256"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"integrity"}</span>{" sha256"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"group"}</span>{" 14"}</div><div className="code-line"><span className={"t-kw"}>{"crypto"}</span>{" ikev2 policy POL"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"proposal"}</span>{" PROP"}</div><div className="code-line"><span className={"t-kw"}>{"crypto"}</span>{" ikev2 keyring KR"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"peer"}</span>{" SITE-B"}</div><div className="code-line">{"  "}<span className={"t-sub"}>{"address"}</span>{" "}<span className={"t-n"}>{"198.51.100.2"}</span></div><div className="code-line">{"  "}<span className={"t-sub"}>{"pre-shared-key"}</span>{" local "}<span className={"t-ph"}>{"<PSK>"}</span></div><div className="code-line">{"  "}<span className={"t-sub"}>{"pre-shared-key"}</span>{" remote "}<span className={"t-ph"}>{"<PSK>"}</span></div><div className="code-line"><span className={"t-kw"}>{"crypto"}</span>{" ikev2 profile PROF"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"match"}</span>{" identity remote address "}<span className={"t-n"}>{"198.51.100.2"}</span>{" "}<span className={"t-n"}>{"255.255.255.255"}</span></div><div className="code-line">{" "}<span className={"t-sub"}>{"authentication"}</span>{" local pre-share"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"authentication"}</span>{" remote pre-share"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"keyring"}</span>{" local KR"}</div><div className="code-line"><span className={"t-kw"}>{"crypto"}</span>{" ipsec transform-set TS esp-aes 256 esp-sha256-hmac"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"mode"}</span>{" tunnel"}</div><div className="code-line"><span className={"t-kw"}>{"crypto"}</span>{" ipsec profile IPSEC-PROF"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"set"}</span>{" transform-set TS"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"set"}</span>{" ikev2-profile PROF"}</div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"interface"}</span>{" Tunnel0"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"ip"}</span>{" address "}<span className={"t-n"}>{"10.255.0.1"}</span>{" "}<span className={"t-n"}>{"255.255.255.252"}</span></div><div className="code-line">{" "}<span className={"t-sub"}>{"tunnel"}</span>{" source GigabitEthernet0/0/0"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"tunnel"}</span>{" destination "}<span className={"t-n"}>{"198.51.100.2"}</span></div><div className="code-line">{" "}<span className={"t-sub"}>{"tunnel"}</span>{" mode ipsec ipv4"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"tunnel"}</span>{" protection ipsec profile IPSEC-PROF"}</div></div>{"\n                    "}</div>{"\n                    "}<p>{"\n                        確認: "}<code>{"show crypto ikev2 sa"}</code>{"、"}<code>{"show crypto ipsec sa"}</code>{"、"}<code>{"show interface tunnel 0"}</code>{"\n                    "}</p>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<ol>{"\n                                "}<li>{"\n                                    鍵は"}<strong>{"強力なアルゴリズム（AES-256、SHA-256 以上、DH グループ 14\n                                        以上）"}</strong>{"を使い、共有鍵をコンフィグへ平文で残さない（証明書認証や鍵管理の仕組みを使う）。\n                                "}</li>{"\n                                "}<li>{"\n                                    トンネルの "}<strong>{"MTU/MSS"}</strong>{"（"}<code>{"ip mtu"}</code>{"、"}<code>{"ip tcp adjust-mss"}</code>{"）を調整し、フラグメントを避ける。\n                                "}</li>{"\n                                "}<li>{"\n                                    トンネル越しのルーティングでは、"}<strong>{"トンネル宛先への経路がトンネル自身経由にならない"}</strong>{"よう注意（再帰ルーティングによるフラップ防止）。\n                                "}</li>{"\n                            "}</ol>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h4 id={"23-ネットワーク仮想化の概念"}>{"2.3 ネットワーク仮想化の概念"}</h4>{"\n                    "}<h5 id={"23a-lisplocatorid-separation-protocol"}>{"\n                        2.3.a LISP（Locator/ID Separation Protocol）\n                    "}</h5>{"\n                    "}<p>{"\n                        "}<strong>{"「誰か（EID）」と「どこにいるか（RLOC）」を分離"}</strong>{"するプロトコルです（RFC 9300）。端末が移動しても EID は変わらず、RLOC\n                        への対応関係だけを更新します。SD-Access のコントロールプレーンで使われます。\n                    "}</p>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"2.3 ネットワーク仮想化の概念（表 16）"}><thead><tr><th scope="col">{"用語"}{" "}</th><th scope="col">{"意味"}{" "}</th></tr></thead><tbody><tr><td>{"EID"}{" "}</td><td>{"端末の識別子（エンドポイントアドレス）"}{" "}</td></tr><tr><td>{"RLOC"}{" "}</td><td>{"ルータのロケータ（トンネルの終端アドレス）"}{" "}</td></tr><tr><td>{"Map-Server / Map-Resolver"}{" "}</td><td>{"EID と RLOC の対応を登録・解決するサーバ"}{" "}</td></tr><tr><td>{"ITR / ETR"}{" "}</td><td>{"カプセル化する側／解除する側のルータ"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<h5 id={"23b-vxlan"}>{"2.3.b VXLAN"}</h5>{"\n                    "}<p>{"\n                        L2 フレームを "}<strong>{"UDP（宛先ポート 4789）でカプセル化"}</strong>{"し、L3\n                        ネットワーク上に L2 セグメントを延伸する技術です（RFC 7348）。"}<strong>{"24 ビットの VNI"}</strong>{"\n                        により約 1,600 万のセグメントを識別でき、VLAN の 4,094\n                        という上限を超えられます。\n                    "}</p>{"\n                    "}<Diagram id="dg9" label={"2.3 ネットワーク仮想化の概念"} />{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"2.3 ネットワーク仮想化の概念（表 17）"}><thead><tr><th scope="col">{"比較"}{" "}</th><th scope="col">{"VLAN"}{" "}</th><th scope="col">{"VXLAN"}{" "}</th></tr></thead><tbody><tr><td>{"セグメント数"}{" "}</td><td>{"4,094（12 ビット）"}{" "}</td><td>{"約 1,600 万（24 ビット VNI）"}{" "}</td></tr><tr><td>{"転送"}{" "}</td><td>{"L2（STP に依存しやすい）"}{" "}</td><td>{"L3 アンダーレイ上（ECMP を活用）"}{" "}</td></tr><tr><td>{"用途"}{" "}</td><td>{"キャンパス、小規模"}{" "}</td><td>{"ファブリック（SD-Access 等）、DC"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                アンダーレイの "}<strong>{"MTU を余裕を持って拡張"}</strong>{"（VXLAN\n                                のオーバーヘッド分）し、エンドツーエンドで一貫させる。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                "}</section>
<section className={"sec sub"} id={"23-インフラストラクチャ30"}>{"\n                    "}<h3 id={"23-インフラストラクチャ30"}>{"2.3 インフラストラクチャ（30%）"}</h3>{"\n                    "}<p>{"最も配点が大きいドメインです。ここを確実に押さえることが合格の近道です。"}</p>{"\n                    "}<h4 id={"31-レイヤ-2"}>{"3.1 レイヤ 2"}</h4>{"\n                    "}<h5 id={"31a-8021q-トランキング静的動的のトラブルシュート"}>{"\n                        3.1.a 802.1Q トランキング（静的・動的）のトラブルシュート\n                    "}</h5>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"3.1 レイヤ 2（表 18）"}><thead><tr><th scope="col">{"項目"}{" "}</th><th scope="col">{"内容"}{" "}</th></tr></thead><tbody><tr><td>{"802.1Q"}{" "}</td><td>{"\n                                        フレームに VLAN タグを付け、1 本のリンクで複数 VLAN を運ぶ\n                                    "}{" "}</td></tr><tr><td>{"ネイティブ VLAN"}{" "}</td><td>{"\n                                        タグなしで運ばれる VLAN。"}<strong>{"両端で一致"}</strong>{"させる\n                                    "}{" "}</td></tr><tr><td>{"DTP"}{" "}</td><td>{"\n                                        トランクを自動ネゴシエーションするプロトコル（dynamic auto /\n                                        dynamic desirable）\n                                    "}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"interface"}</span>{" GigabitEthernet1/0/48"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"switchport"}</span>{" mode trunk"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"switchport"}</span>{" nonegotiate"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"switchport"}</span>{" trunk native vlan 999"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"switchport"}</span>{" trunk allowed vlan 10,20,30"}</div></div>{"\n                    "}</div>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<ol>{"\n                                "}<li>{"\n                                    "}<strong>{"DTP に頼らず静的に\n                                        "}<code>{"switchport mode trunk"}</code></strong>{"\n                                    を設定し、"}<code>{"switchport nonegotiate"}</code>{" で DTP を止める。\n                                "}</li>{"\n                                "}<li>{"\n                                    ネイティブ VLAN は"}<strong>{"未使用の専用 VLAN"}</strong>{"にして両端で揃える（VLAN 1 を避ける）。\n                                "}</li>{"\n                                "}<li>{"\n                                    "}<code>{"allowed vlan"}</code>{" で"}<strong>{"必要な VLAN だけ"}</strong>{"を通す（プルーニング）。\n                                "}</li>{"\n                            "}</ol>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<Diagram id="dg10" label={"3.1 レイヤ 2"} />{"\n                    "}<h5 id={"31b-静的動的-etherchannel-のトラブルシュート"}>{"\n                        3.1.b 静的・動的 EtherChannel のトラブルシュート\n                    "}</h5>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"3.1 レイヤ 2（表 19）"}><thead><tr><th scope="col">{"モード"}{" "}</th><th scope="col">{"プロトコル"}{" "}</th><th scope="col">{"組み合わせ"}{" "}</th></tr></thead><tbody><tr><td>{"active / passive"}{" "}</td><td><strong>{"LACP（IEEE 802.3ad）"}</strong>{" "}</td><td>{"\n                                        active–active、active–passive は成立。passive–passive\n                                        は不成立\n                                    "}{" "}</td></tr><tr><td>{"desirable / auto"}{" "}</td><td>{"PAgP（Cisco 独自）"}{" "}</td><td>{"desirable–desirable、desirable–auto は成立"}{" "}</td></tr><tr><td>{"on"}{" "}</td><td>{"静的（ネゴシエーションなし）"}{" "}</td><td>{"on–on のみ成立"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"interface"}</span>{" range GigabitEthernet1/0/1 - 2"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"channel-group"}</span>{" 1 mode active"}</div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"interface"}</span>{" Port-channel1"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"switchport"}</span>{" mode trunk"}</div></div>{"\n                    "}</div>{"\n                    "}<p>{"\n                        確認: "}<code>{"show etherchannel summary"}</code>{"（フラグ "}<code>{"SU"}</code>{" =\n                        正常、"}<code>{"SD"}</code>{" / "}<code>{"I"}</code>{" / "}<code>{"s"}</code>{" = 要調査）\n                    "}</p>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                標準の "}<strong>{"LACP を推奨"}</strong>{"。"}<strong>{"速度・デュプレックス・トランク／VLAN 設定・ネイティブ VLAN\n                                    を全メンバーで統一"}</strong>{"する。設定変更は Port-channel インターフェイス側で行う。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h5 id={"31c-スパニングツリーrstpmstと拡張機能"}>{"\n                        3.1.c スパニングツリー（RSTP、MST）と拡張機能\n                    "}</h5>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"3.1 レイヤ 2（表 20）"}><thead><tr><th scope="col">{"項目"}{" "}</th><th scope="col">{"PVST+ / Rapid PVST+"}{" "}</th><th scope="col">{"MST（802.1s）"}{" "}</th></tr></thead><tbody><tr><td>{"単位"}{" "}</td><td>{"VLAN ごとにインスタンス"}{" "}</td><td>{"複数 VLAN を"}<strong>{"インスタンスにマッピング"}</strong>{" "}</td></tr><tr><td>{"特徴"}{" "}</td><td>{"シンプル。VLAN 数が多いと負荷増"}{" "}</td><td>{"大規模 VLAN 環境で CPU 負荷とメモリを削減"}{" "}</td></tr><tr><td>{"注意"}{" "}</td><td>{"—"}{" "}</td><td>{"\n                                        リージョン名・リビジョン・VLAN\n                                        マッピングを"}<strong>{"全スイッチで一致"}</strong>{"させる\n                                    "}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<p>{"\n                        RSTP（802.1w）のポート役割:\n                        ルート／代替（Alternate）／指定／バックアップ。ポート状態:\n                        Discarding／Learning／Forwarding。\n                    "}</p>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"3.1 レイヤ 2（表 21）"}><thead><tr><th scope="col">{"拡張機能"}{" "}</th><th scope="col">{"役割"}{" "}</th></tr></thead><tbody><tr><td><strong>{"PortFast"}</strong>{" "}</td><td>{"エッジポート（端末側）を即座に Forwarding へ"}{" "}</td></tr><tr><td><strong>{"BPDU Guard"}</strong>{" "}</td><td>{"\n                                        PortFast ポートで BPDU を受信したら\n                                        "}<strong>{"err-disable"}</strong>{" にする\n                                    "}{" "}</td></tr><tr><td><strong>{"Root Guard"}</strong>{" "}</td><td>{"\n                                        想定外のスイッチがルートになるのを防ぐ（優位 BPDU\n                                        を受けたらブロック）\n                                    "}{" "}</td></tr><tr><td><strong>{"Loop Guard"}</strong>{" "}</td><td>{"\n                                        BPDU が途絶えた非指定ポートが Forwarding\n                                        へ誤遷移するのを防ぐ\n                                    "}{" "}</td></tr><tr><td><strong>{"UDLD"}</strong>{" "}</td><td>{"片方向リンク障害を検知"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"spanning-tree"}</span>{" mode rapid-pvst"}</div><div className="code-line"><span className={"t-kw"}>{"spanning-tree"}</span>{" vlan 10,20 root primary"}</div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"interface"}</span>{" GigabitEthernet1/0/10"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"switchport"}</span>{" mode access"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"switchport"}</span>{" access vlan 10"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"spanning-tree"}</span>{" portfast"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"spanning-tree"}</span>{" bpduguard enable"}</div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"interface"}</span>{" GigabitEthernet1/0/47"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"description"}</span>{" to-downstream-switch"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"spanning-tree"}</span>{" guard root"}</div></div>{"\n                    "}</div>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<ol>{"\n                                "}<li>{"\n                                    "}<strong>{"ルートブリッジを意図して固定"}</strong>{"（プライオリティ設定、または\n                                    "}<code>{"root primary/secondary"}</code>{"）し、FHRP\n                                    のアクティブとも揃える。\n                                "}</li>{"\n                                "}<li>{"\n                                    端末ポートには\n                                    "}<strong>{"PortFast + BPDU Guard"}</strong>{" を必ずセットで適用する。\n                                "}</li>{"\n                                "}<li>{"\n                                    アクセスからの上位への接続でルートが動かないよう、"}<strong>{"境界に Root Guard"}</strong>{"\n                                    を入れる。\n                                "}</li>{"\n                                "}<li>{"\n                                    大規模な VLAN 環境では\n                                    "}<strong>{"MST"}</strong>{"\n                                    を検討し、リージョン設定の一致を運用で厳守する。\n                                "}</li>{"\n                            "}</ol>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h4 id={"32-レイヤ-3"}>{"3.2 レイヤ 3"}</h4>{"\n                    "}<h5 id={"32a-eigrp-と-ospf-のルーティング概念の比較"}>{"\n                        3.2.a EIGRP と OSPF のルーティング概念の比較\n                    "}</h5>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"3.2 レイヤ 3（表 22）"}><thead><tr><th scope="col">{"観点"}{" "}</th><th scope="col">{"EIGRP"}{" "}</th><th scope="col">{"OSPF"}{" "}</th></tr></thead><tbody><tr><td>{"方式"}{" "}</td><td>{"\n                                        "}<strong>{"拡張ディスタンスベクター"}</strong>{"（DUAL\n                                        アルゴリズム）\n                                    "}{" "}</td><td><strong>{"リンクステート"}</strong>{"（SPF アルゴリズム）"}{" "}</td></tr><tr><td>{"メトリック"}{" "}</td><td>{"帯域・遅延（既定。信頼性・負荷は通常使用しない）"}{" "}</td><td>{"コスト（基準帯域 ÷ インターフェイス帯域）"}{" "}</td></tr><tr><td>{"AD"}{" "}</td><td>{"内部 90／外部 170"}{" "}</td><td>{"110"}{" "}</td></tr><tr><td>{"ロードバランス"}{" "}</td><td>{"等コスト＋"}<strong>{"不等コスト（variance）"}</strong>{" "}</td><td>{"等コスト（ECMP）"}{" "}</td></tr><tr><td>{"構造"}{" "}</td><td>{"フラット（要約・スタブで制御）"}{" "}</td><td>{"\n                                        "}<strong>{"エリア"}</strong>{"による階層（バックボーン Area 0）\n                                    "}{" "}</td></tr><tr><td>{"収束"}{" "}</td><td>{"フィージブルサクセサがあれば即時"}{" "}</td><td>{"LSA 伝播＋SPF 再計算"}{" "}</td></tr><tr><td>{"規格"}{" "}</td><td>{"Cisco 主導（RFC 7868 で公開）"}{" "}</td><td>{"標準（RFC 2328 / RFC 5340）"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<p>{"\n                        EIGRP の要点:\n                        最良経路（サクセサ）／バックアップ候補（"}<strong>{"フィージブルサクセサ"}</strong>{"）。"}<strong>{"FD（Feasible Distance）"}</strong>{"と"}<strong>{"RD（Reported Distance）"}</strong>{"を比較し、"}<code>{"RD < 現在の FD"}</code>{"\n                        ならループフリーと判断（フィージブル条件）。\n                    "}</p>{"\n                    "}<p>{"OSPF のエリアタイプ:"}</p>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"3.2 レイヤ 3（表 23）"}><thead><tr><th scope="col">{"エリア"}{" "}</th><th scope="col">{"外部経路（LSA 5）"}{" "}</th><th scope="col">{"特徴"}{" "}</th></tr></thead><tbody><tr><td>{"標準"}{" "}</td><td>{"受け入れる"}{" "}</td><td>{"通常のエリア"}{" "}</td></tr><tr><td>{"スタブ"}{" "}</td><td>{"受け入れない（デフォルトルートで代替）"}{" "}</td><td>{"LSDB を縮小"}{" "}</td></tr><tr><td>{"トータリースタブ"}{" "}</td><td>{"外部＋他エリア経路も受け入れない"}{" "}</td><td>{"さらに縮小（Cisco 拡張）"}{" "}</td></tr><tr><td>{"NSSA"}{" "}</td><td>{"内部の ASBR で外部経路を導入可（LSA 7）"}{" "}</td><td>{"スタブ的に外部を取り込みたい場合"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<h5 id={"32b-ospfv2v3-の設定複数エリア要約フィルタリングネットワークタイプ"}>{"\n                        3.2.b OSPFv2/v3\n                        の設定（複数エリア、要約、フィルタリング、ネットワークタイプ）\n                    "}</h5>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"router"}</span>{" ospf 1"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"router-id"}</span>{" "}<span className={"t-n"}>{"1.1.1.1"}</span></div><div className="code-line">{" "}<span className={"t-sub"}>{"passive-interface"}</span>{" default"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"no"}</span>{" passive-interface GigabitEthernet0/0/0"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"area"}</span>{" 10 range "}<span className={"t-n"}>{"10.10.0.0"}</span>{" "}<span className={"t-n"}>{"255.255.0.0"}</span>{"      "}<span className={"t-cm"}>{"! ABR での経路要約"}</span></div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"interface"}</span>{" GigabitEthernet0/0/0"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"ip"}</span>{" ospf 1 area 10"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"ip"}</span>{" ospf network point-to-point          "}<span className={"t-cm"}>{"! DR/BDR 選出を省略して高速化"}</span></div><div className="code-line">{" "}<span className={"t-sub"}>{"ip"}</span>{" ospf authentication message-digest"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"ip"}</span>{" ospf message-digest-key 1 md5 "}<span className={"t-ph"}>{"<KEY>"}</span></div></div>{"\n                    "}</div>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-cm"}>{"! OSPFv3（IPv6）"}</span></div><div className="code-line"><span className={"t-kw"}>{"ipv6"}</span>{" unicast-routing"}</div><div className="code-line"><span className={"t-kw"}>{"ipv6"}</span>{" router ospf 1"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"router-id"}</span>{" "}<span className={"t-n"}>{"1.1.1.1"}</span></div><div className="code-line"><span className={"t-kw"}>{"interface"}</span>{" GigabitEthernet0/0/0"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"ipv6"}</span>{" ospf 1 area 10"}</div></div>{"\n                    "}</div>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"3.2 レイヤ 3（表 24）"}><thead><tr><th scope="col">{"ネットワークタイプ"}{" "}</th><th scope="col">{"DR/BDR"}{" "}</th><th scope="col">{"典型"}{" "}</th></tr></thead><tbody><tr><td>{"ブロードキャスト"}{" "}</td><td>{"選出あり"}{" "}</td><td>{"イーサネット（既定）"}{" "}</td></tr><tr><td>{"ポイントツーポイント"}{" "}</td><td>{"なし"}{" "}</td><td>{"2 拠点間リンク（イーサネットでも設定可）"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<Diagram id="dg11" label={"3.2 レイヤ 3"} />{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<ol>{"\n                                "}<li>{"\n                                    "}<strong>{"ルータ ID を固定"}</strong>{"（明示設定）。ループバックを使い、変更で SPF\n                                    が乱れないようにする。\n                                "}</li>{"\n                                "}<li>{"\n                                    "}<strong><code>{"passive-interface default"}</code></strong>{"\n                                    を基本とし、ネイバーが必要なインターフェイスのみ解除する（不要なネイバー形成・攻撃面を排除）。\n                                "}</li>{"\n                                "}<li>{"\n                                    ABR で"}<strong>{"経路を要約"}</strong>{"し、LSDB と SPF\n                                    の影響範囲を小さくする。\n                                "}</li>{"\n                                "}<li><strong>{"認証を有効化"}</strong>{"して不正なルータの参加を防ぐ。"}</li>{"\n                                "}<li>{"\n                                    1\n                                    つのエリアの規模は適度に保ち、エリア設計はアドレス設計と揃える。\n                                "}</li>{"\n                            "}</ol>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h5 id={"32c-直接接続ネイバー間の-ebgp最適パス選択とネイバー関係"}>{"\n                        3.2.c 直接接続ネイバー間の eBGP（最適パス選択とネイバー関係）\n                    "}</h5>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"router"}</span>{" bgp 65001"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"bgp"}</span>{" router-id "}<span className={"t-n"}>{"1.1.1.1"}</span></div><div className="code-line">{" "}<span className={"t-sub"}>{"neighbor"}</span>{" "}<span className={"t-n"}>{"203.0.113.2"}</span>{" remote-as 65002"}</div><div className="code-line">{" "}<span className={"t-cm"}>{"!"}</span></div><div className="code-line">{" "}<span className={"t-sub"}>{"address-family"}</span>{" ipv4 unicast"}</div><div className="code-line">{"  "}<span className={"t-sub"}>{"neighbor"}</span>{" "}<span className={"t-n"}>{"203.0.113.2"}</span>{" activate"}</div><div className="code-line">{"  "}<span className={"t-sub"}>{"network"}</span>{" "}<span className={"t-n"}>{"10.10.0.0"}</span>{" mask "}<span className={"t-n"}>{"255.255.0.0"}</span></div></div>{"\n                    "}</div>{"\n                    "}<p>{"\n                        "}<strong>{"ネイバー状態の流れ"}</strong>{": Idle → Connect → Active → OpenSent →\n                        OpenConfirm → "}<strong>{"Established"}</strong>{"（Established が正常）。BGP は TCP\n                        179 を使用します。\n                    "}</p>{"\n                    "}<p><strong>{"最適パス選択（上位から順に評価）"}</strong></p>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"3.2 レイヤ 3（表 25）"}><thead><tr><th scope="col">{"順"}{" "}</th><th scope="col">{"属性"}{" "}</th><th scope="col">{"優先"}{" "}</th></tr></thead><tbody><tr><td>{"1"}{" "}</td><td>{"Weight（Cisco 独自・ローカル）"}{" "}</td><td>{"大きい方"}{" "}</td></tr><tr><td>{"2"}{" "}</td><td>{"LOCAL_PREF"}{" "}</td><td>{"大きい方"}{" "}</td></tr><tr><td>{"3"}{" "}</td><td>{"ローカル生成（network/redistribute/aggregate）"}{" "}</td><td>{"自ルータ起源を優先"}{" "}</td></tr><tr><td>{"4"}{" "}</td><td>{"AS_PATH 長"}{" "}</td><td>{"短い方"}{" "}</td></tr><tr><td>{"5"}{" "}</td><td>{"Origin"}{" "}</td><td>{"IGP < EGP < Incomplete"}{" "}</td></tr><tr><td>{"6"}{" "}</td><td>{"MED"}{" "}</td><td>{"小さい方"}{" "}</td></tr><tr><td>{"7"}{" "}</td><td>{"eBGP と iBGP"}{" "}</td><td>{"eBGP を優先"}{" "}</td></tr><tr><td>{"8"}{" "}</td><td>{"ネクストホップへの IGP メトリック"}{" "}</td><td>{"小さい方"}{" "}</td></tr><tr><td>{"9〜"}{" "}</td><td>{"古さ／ルータ ID など"}{" "}</td><td>{"タイブレーク"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<Diagram id="dg12" label={"3.2 レイヤ 3"} />{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<ol>{"\n                                "}<li>{"\n                                    "}<strong>{"ネイバーごとに認証"}</strong>{"（MD5 または TCP-AO\n                                    等）を設定し、"}<strong>{"受信経路数の上限（maximum-prefix）"}</strong>{"を設ける。\n                                "}</li>{"\n                                "}<li>{"\n                                    インバウンド／アウトバウンドに"}<strong>{"プレフィックスフィルタと AS_PATH フィルタ"}</strong>{"を適用し、意図しない経路の受信・広告を防ぐ（BGP\n                                    運用のセキュリティは RFC 7454 を参照）。\n                                "}</li>{"\n                                "}<li>{"\n                                    経路の広告は"}<strong>{"明示的な network 文とフィルタ"}</strong>{"で管理し、再配布による広告漏れ・漏洩を避ける。\n                                "}</li>{"\n                            "}</ol>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h5 id={"32d-ポリシーベースルーティングpbr"}>{"\n                        3.2.d ポリシーベースルーティング（PBR）\n                    "}</h5>{"\n                    "}<p>{"\n                        宛先だけでなく"}<strong>{"送信元・プロトコル・ポートなど"}</strong>{"に基づいて次ホップを選ぶ仕組みです。\n                    "}</p>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"ip"}</span>{" access-list extended GUEST-TRAFFIC"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"permit"}</span>{" ip "}<span className={"t-n"}>{"10.20.0.0"}</span>{" "}<span className={"t-n"}>{"0.0.255.255"}</span>{" any"}</div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"route-map"}</span>{" PBR-GUEST permit 10"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"match"}</span>{" ip address GUEST-TRAFFIC"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"set"}</span>{" ip next-hop "}<span className={"t-n"}>{"192.0.2.254"}</span></div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"interface"}</span>{" GigabitEthernet0/0/1"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"ip"}</span>{" policy route-map PBR-GUEST"}</div></div>{"\n                    "}</div>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                次ホップの"}<strong>{"到達性を追跡（"}<code>{"set ip next-hop verify-availability"}</code>{"\n                                    や IP SLA＋track）"}</strong>{"して、障害時に黙って落ちないようにする。PBR\n                                は運用を複雑にするため、"}<strong>{"最小限の適用"}</strong>{"に留める。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h4 id={"33-ip-サービス"}>{"3.3 IP サービス"}</h4>{"\n                    "}<h5 id={"33a-ntp-と-ptp"}>{"3.3.a NTP と PTP"}</h5>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"3.3 IP サービス（表 26）"}><thead><tr><th scope="col">{"項目"}{" "}</th><th scope="col">{"NTP"}{" "}</th><th scope="col">{"PTP（IEEE 1588）"}{" "}</th></tr></thead><tbody><tr><td>{"精度"}{" "}</td><td>{"ミリ秒レベル"}{" "}</td><td>{"サブマイクロ秒〜ナノ秒レベル（ハードウェア支援）"}{" "}</td></tr><tr><td>{"用途"}{" "}</td><td>{"ログ・証明書・認証の時刻整合（ほぼ全機器）"}{" "}</td><td>{"金融、放送、産業用など高精度が必要な環境"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"ntp"}</span>{" authenticate"}</div><div className="code-line"><span className={"t-kw"}>{"ntp"}</span>{" authentication-key 1 md5 "}<span className={"t-ph"}>{"<KEY>"}</span></div><div className="code-line"><span className={"t-kw"}>{"ntp"}</span>{" trusted-key 1"}</div><div className="code-line"><span className={"t-kw"}>{"ntp"}</span>{" server "}<span className={"t-n"}>{"192.0.2.123"}</span>{" key 1"}</div><div className="code-line"><span className={"t-kw"}>{"clock"}</span>{" timezone JST 9 0"}</div></div>{"\n                    "}</div>{"\n                    "}<p>{"確認: "}<code>{"show ntp status"}</code>{"、"}<code>{"show ntp associations"}</code></p>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                複数の NTP サーバー（できれば 3\n                                台以上）を参照し、"}<strong>{"認証を有効化"}</strong>{"する。全機器で時刻を揃えることで、ログ相関とトラブルシュートが正確になる。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h5 id={"33b-nat--pat"}>{"3.3.b NAT / PAT"}</h5>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"3.3 IP サービス（表 27）"}><thead><tr><th scope="col">{"種類"}{" "}</th><th scope="col">{"内容"}{" "}</th></tr></thead><tbody><tr><td>{"スタティック NAT"}{" "}</td><td>{"1 対 1 の固定変換（サーバー公開等）"}{" "}</td></tr><tr><td>{"ダイナミック NAT"}{" "}</td><td>{"プールから動的に 1 対 1"}{" "}</td></tr><tr><td>{"PAT（オーバーロード）"}{" "}</td><td>{"\n                                        1 つのグローバル IP を"}<strong>{"ポート番号で多重化"}</strong>{"\n                                    "}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"3.3 IP サービス（表 28）"}><thead><tr><th scope="col">{"用語"}{" "}</th><th scope="col">{"意味"}{" "}</th></tr></thead><tbody><tr><td>{"Inside Local"}{" "}</td><td>{"内側ホストの内部アドレス"}{" "}</td></tr><tr><td>{"Inside Global"}{" "}</td><td>{"内側ホストが外側から見えるアドレス"}{" "}</td></tr><tr><td>{"Outside Local / Global"}{" "}</td><td>{"外側ホストの内側から／外側から見えるアドレス"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"interface"}</span>{" GigabitEthernet0/0/0"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"ip"}</span>{" nat outside"}</div><div className="code-line"><span className={"t-kw"}>{"interface"}</span>{" GigabitEthernet0/0/1"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"ip"}</span>{" nat inside"}</div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"access-list"}</span>{" 10 permit "}<span className={"t-n"}>{"10.0.0.0"}</span>{" "}<span className={"t-n"}>{"0.0.255.255"}</span></div><div className="code-line"><span className={"t-kw"}>{"ip"}</span>{" nat inside source list 10 interface GigabitEthernet0/0/0 overload"}</div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-cm"}>{"! スタティック NAT（サーバー公開）"}</span></div><div className="code-line"><span className={"t-kw"}>{"ip"}</span>{" nat inside source static "}<span className={"t-n"}>{"10.0.0.10"}</span>{" "}<span className={"t-n"}>{"203.0.113.10"}</span></div></div>{"\n                    "}</div>{"\n                    "}<p>{"\n                        確認: "}<code>{"show ip nat translations"}</code>{"、"}<code>{"show ip nat statistics"}</code>{"\n                    "}</p>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                inside／outside\n                                の指定漏れが最多の原因。変換テーブルの"}<strong>{"タイムアウトと上限"}</strong>{"を把握し、NAT\n                                ログ（NetFlow/syslog）で追跡可能にしておく。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h5 id={"33c-fhrphsrpvrrp"}>{"3.3.c FHRP（HSRP、VRRP）"}</h5>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"3.3 IP サービス（表 29）"}><thead><tr><th scope="col">{"項目"}{" "}</th><th scope="col">{"HSRP"}{" "}</th><th scope="col">{"VRRP"}{" "}</th></tr></thead><tbody><tr><td>{"規格"}{" "}</td><td>{"Cisco 独自"}{" "}</td><td>{"標準（RFC 5798）"}{" "}</td></tr><tr><td>{"役割名"}{" "}</td><td>{"Active／Standby"}{" "}</td><td>{"Master／Backup"}{" "}</td></tr><tr><td>{"仮想 MAC"}{" "}</td><td>{"0000.0C07.ACxx（v1）／0000.0C9F.Fxxx（v2）"}{" "}</td><td>{"0000.5E00.01xx"}{" "}</td></tr><tr><td>{"Hello の宛先"}{" "}</td><td>{"224.0.0.2（v1）／224.0.0.102（v2）"}{" "}</td><td>{"224.0.0.18"}{" "}</td></tr><tr><td>{"プリエンプト"}{" "}</td><td>{"既定は無効（有効化が必要）"}{" "}</td><td>{"既定で有効"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"interface"}</span>{" Vlan10"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"ip"}</span>{" address "}<span className={"t-n"}>{"10.10.10.2"}</span>{" "}<span className={"t-n"}>{"255.255.255.0"}</span></div><div className="code-line">{" "}<span className={"t-sub"}>{"standby"}</span>{" version 2"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"standby"}</span>{" 10 ip "}<span className={"t-n"}>{"10.10.10.1"}</span></div><div className="code-line">{" "}<span className={"t-sub"}>{"standby"}</span>{" 10 priority 110"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"standby"}</span>{" 10 preempt"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"standby"}</span>{" 10 track 1 decrement 20"}</div></div>{"\n                    "}</div>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<ol>{"\n                                "}<li>{"\n                                    "}<strong>{"STP のルートブリッジ、FHRP\n                                        のアクティブ、（可能なら）ルーティングの最適経路を同じ機器に揃える"}</strong>{"。\n                                "}</li>{"\n                                "}<li>{"\n                                    "}<strong>{"preempt を有効化"}</strong>{"し、上位リンクのダウン時は"}<strong>{"トラッキングで優先度を下げて"}</strong>{"切り替える。\n                                "}</li>{"\n                                "}<li>{"\n                                    FHRP の認証を有効化し、VLAN\n                                    単位で"}<strong>{"アクティブを分散"}</strong>{"して負荷を分ける（VLAN\n                                    ごとに役割をずらす）。\n                                "}</li>{"\n                            "}</ol>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h5 id={"33d-マルチキャストプロトコルrpf-チェックpim-smigmpssmbidirmsdp"}>{"\n                        3.3.d マルチキャストプロトコル（RPF\n                        チェック、PIM-SM、IGMP、SSM、bidir、MSDP）\n                    "}</h5>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"3.3 IP サービス（表 30）"}><thead><tr><th scope="col">{"要素"}{" "}</th><th scope="col">{"役割"}{" "}</th></tr></thead><tbody><tr><td><strong>{"IGMP v2/v3"}</strong>{" "}</td><td>{"\n                                        ホストがグループ参加・離脱を LAN 上のルータに通知（v3\n                                        は送信元指定が可能）\n                                    "}{" "}</td></tr><tr><td><strong>{"RPF チェック"}</strong>{" "}</td><td>{"\n                                        「送信元へ戻る最短経路の"}<strong>{"入力インターフェイス"}</strong>{"で受信したパケットのみ転送」しループを防止\n                                    "}{" "}</td></tr><tr><td><strong>{"PIM-SM"}</strong>{" "}</td><td>{"\n                                        ランデブーポイント（RP）を起点に"}<strong>{"共有ツリー"}</strong>{"を作り、その後"}<strong>{"最短経路ツリー（SPT）"}</strong>{"へ切替\n                                    "}{" "}</td></tr><tr><td><strong>{"SSM"}</strong>{" "}</td><td>{"\n                                        送信元を指定して購読（IGMPv3）。RP 不要。範囲は既定で\n                                        232.0.0.0/8\n                                    "}{" "}</td></tr><tr><td><strong>{"PIM bidir"}</strong>{" "}</td><td>{"\n                                        双方向共有ツリー。多数の送信元・受信者が混在する用途に適する\n                                    "}{" "}</td></tr><tr><td><strong>{"MSDP"}</strong>{" "}</td><td>{"ドメイン間で RP が送信元情報を交換"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<Diagram id="dg13" label={"3.3 IP サービス"} />{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"ip"}</span>{" multicast-routing"}</div><div className="code-line"><span className={"t-kw"}>{"interface"}</span>{" GigabitEthernet0/0/1"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"ip"}</span>{" pim sparse-mode"}</div><div className="code-line"><span className={"t-kw"}>{"ip"}</span>{" pim rp-address "}<span className={"t-n"}>{"192.0.2.100"}</span></div></div>{"\n                    "}</div>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                全 L3 インターフェイスで PIM を有効化する一貫性を保つ。RP\n                                は"}<strong>{"冗長化"}</strong>{"（Anycast RP\n                                等）を検討する。トラブル時はまず "}<strong>{"RPF の失敗"}</strong>{"（"}<code>{"show ip rpf <送信元>"}</code>{"）を疑う。SSM は RP\n                                管理が不要で運用が単純になるため、用途が合えば優先して採用する。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                "}</section>
<section className={"sec sub"} id={"24-ネットワークアシュアランス10"}>{"\n                    "}<h3 id={"24-ネットワークアシュアランス10"}>{"\n                        2.4 ネットワークアシュアランス（10%）\n                    "}</h3>{"\n                    "}<p>{"\n                        "}<strong>{"なぜ必要か"}</strong>{":\n                        障害は「起きてから」ではなく「兆候の段階」で見つけたいものです。ログ・フロー・時間指標・モデル駆動データを組み合わせて、"}<strong>{"原因の切り分けを速く、証拠付きで"}</strong>{"行います。\n                    "}</p>{"\n                    "}<h4 id={"41-問題の診断debug条件付き-debugtraceroutepingsnmpsyslog"}>{"\n                        4.1 問題の診断（debug、条件付き debug、traceroute、ping、SNMP、syslog）\n                    "}</h4>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"4.1 問題の診断（debug、条件付き debug、traceroute、ping、SNMP、syslog）（表 31）"}><thead><tr><th scope="col">{"ツール"}{" "}</th><th scope="col">{"用途"}{" "}</th><th scope="col">{"注意点"}{" "}</th></tr></thead><tbody><tr><td>{"ping"}{" "}</td><td>{"到達性・遅延の確認"}{" "}</td><td>{"拡張 ping で送信元・サイズ・DF ビットを指定できる"}{" "}</td></tr><tr><td>{"traceroute"}{" "}</td><td>{"経路上のどこで途切れるかを確認"}{" "}</td><td>{"\n                                        途中の "}<code>{"*"}</code>{" は「ICMP を返さない」だけの場合もある\n                                    "}{" "}</td></tr><tr><td>{"debug"}{" "}</td><td>{"内部動作の詳細確認"}{" "}</td><td>{"\n                                        "}<strong>{"CPU 負荷が高い"}</strong>{"。本番では最小限、終わったら必ず "}<code>{"undebug all"}</code>{"\n                                    "}{" "}</td></tr><tr><td>{"条件付き debug"}{" "}</td><td>{"\n                                        特定のインターフェイス・IP・MAC に"}<strong>{"限定"}</strong>{"した\n                                        debug\n                                    "}{" "}</td><td>{"本番での debug の第一選択"}{" "}</td></tr><tr><td>{"syslog"}{" "}</td><td>{"イベントの記録・集約"}{" "}</td><td>{"重大度 0〜7（0 = emergencies … 7 = debugging）"}{" "}</td></tr><tr><td>{"SNMP"}{" "}</td><td>{"状態監視（ポーリング）とトラップ"}{" "}</td><td><strong>{"v3（認証＋暗号化）を使用"}</strong>{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-cm"}>{"! 条件付き debug の例"}</span></div><div className="code-line"><span className={"t-kw"}>{"debug"}</span>{" condition ip "}<span className={"t-n"}>{"192.0.2.50"}</span></div><div className="code-line"><span className={"t-kw"}>{"debug"}</span>{" ip packet detail"}</div><div className="code-line"><span className={"t-cm"}>{"! 終了時"}</span></div><div className="code-line"><span className={"t-kw"}>{"undebug"}</span>{" all"}</div></div>{"\n                    "}</div>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-cm"}>{"! syslog と SNMPv3 の基本例"}</span></div><div className="code-line"><span className={"t-kw"}>{"service"}</span>{" timestamps log datetime msec localtime show-timezone"}</div><div className="code-line"><span className={"t-kw"}>{"logging"}</span>{" host "}<span className={"t-n"}>{"192.0.2.200"}</span></div><div className="code-line"><span className={"t-kw"}>{"logging"}</span>{" trap informational"}</div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"snmp-server"}</span>{" group MON-GRP v3 priv"}</div><div className="code-line"><span className={"t-kw"}>{"snmp-server"}</span>{" user mon-user MON-GRP v3 auth sha "}<span className={"t-ph"}>{"<AUTH-PASS>"}</span>{" priv aes 128 "}<span className={"t-ph"}>{"<PRIV-PASS>"}</span></div></div>{"\n                    "}</div>{"\n                    "}<Diagram id="dg14" label={"4.1 問題の診断（debug、条件付き debug、traceroute、ping、SNMP、syslog）"} />{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<ol>{"\n                                "}<li>{"\n                                    "}<strong>{"全機器の時刻を NTP で同期"}</strong>{"し、ログにミリ秒タイムスタンプを付ける（相関分析のため）。\n                                "}</li>{"\n                                "}<li>{"\n                                    ログは"}<strong>{"集中サーバー"}</strong>{"へ転送し、装置ローカルのバッファだけに頼らない。\n                                "}</li>{"\n                                "}<li>{"\n                                    debug\n                                    は「条件付き」「短時間」「ログ出力先をバッファに」が原則。CPU\n                                    に注意する。\n                                "}</li>{"\n                                "}<li>{"\n                                    SNMP は\n                                    "}<strong>{"v3"}</strong>{"、読み取り専用ユーザーを基本にし、アクセス元を ACL で制限する。\n                                "}</li>{"\n                            "}</ol>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h4 id={"42-flexible-netflow-の設定と確認"}>{"4.2 Flexible NetFlow の設定と確認"}</h4>{"\n                    "}<p>{"\n                        "}<strong>{"フロー"}</strong>{"（送信元/宛先\n                        IP、ポート、プロトコルなどの組で識別される通信）を集計し、"}<strong>{"誰が・どの通信で・どれだけ使ったか"}</strong>{"を可視化します。Flexible\n                        NetFlow は「何を集めるか」をカスタムできるのが特徴です。\n                    "}</p>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"4.2 Flexible NetFlow の設定と確認（表 32）"}><thead><tr><th scope="col">{"構成要素"}{" "}</th><th scope="col">{"役割"}{" "}</th></tr></thead><tbody><tr><td>{"Flow Record"}{" "}</td><td>{"集める項目（match：キー、collect：追加情報）"}{" "}</td></tr><tr><td>{"Flow Exporter"}{" "}</td><td>{"送信先コレクタ（IP、UDP ポート、バージョン）"}{" "}</td></tr><tr><td>{"Flow Monitor"}{" "}</td><td>{"Record と Exporter を結びつけ、インターフェイスに適用"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"flow"}</span>{" record REC-IPV4"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"match"}</span>{" ipv4 source address"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"match"}</span>{" ipv4 destination address"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"match"}</span>{" transport source-port"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"match"}</span>{" transport destination-port"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"match"}</span>{" ipv4 protocol"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"collect"}</span>{" counter bytes"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"collect"}</span>{" counter packets"}</div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"flow"}</span>{" exporter EXP-1"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"destination"}</span>{" "}<span className={"t-n"}>{"192.0.2.201"}</span></div><div className="code-line">{" "}<span className={"t-sub"}>{"transport"}</span>{" udp 2055"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"export-protocol"}</span>{" ipfix"}</div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"flow"}</span>{" monitor MON-1"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"record"}</span>{" REC-IPV4"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"exporter"}</span>{" EXP-1"}</div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"interface"}</span>{" GigabitEthernet1/0/1"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"ip"}</span>{" flow monitor MON-1 input"}</div></div>{"\n                    "}</div>{"\n                    "}<p>{"\n                        確認: "}<code>{"show flow monitor MON-1 cache"}</code>{"、"}<code>{"show flow exporter EXP-1 statistics"}</code>{"\n                    "}</p>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                まず"}<strong>{"境界リンク（WAN・インターネット出口）"}</strong>{"から有効化し、負荷を見ながら広げる。サンプリング（サンプラー）の利用でスイッチ／ルータの負荷を調整する。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h4 id={"43-span--rspan--erspan"}>{"4.3 SPAN / RSPAN / ERSPAN"}</h4>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"4.3 SPAN / RSPAN / ERSPAN（表 33）"}><thead><tr><th scope="col">{"技術"}{" "}</th><th scope="col">{"範囲"}{" "}</th><th scope="col">{"仕組み"}{" "}</th></tr></thead><tbody><tr><td>{"SPAN"}{" "}</td><td>{"同一スイッチ内"}{" "}</td><td>{"ポート／VLAN のトラフィックを別ポートへコピー"}{" "}</td></tr><tr><td>{"RSPAN"}{" "}</td><td>{"L2 ネットワーク越し"}{" "}</td><td>{"専用 VLAN 経由でコピーを別スイッチへ運ぶ"}{" "}</td></tr><tr><td>{"ERSPAN"}{" "}</td><td><strong>{"L3（IP）ネットワーク越し"}</strong>{" "}</td><td>{"GRE でカプセル化してコレクタへ送る"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"monitor"}</span>{" session 1 source interface GigabitEthernet1/0/1 both"}</div><div className="code-line"><span className={"t-kw"}>{"monitor"}</span>{" session 1 destination interface GigabitEthernet1/0/24"}</div></div>{"\n                    "}</div>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                ミラー元の総帯域が宛先ポート帯域を超えるとコピーが"}<strong>{"欠落"}</strong>{"する。宛先ポートは監視専用にし、本番端末を接続しない。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h4 id={"44-ip-sla"}>{"4.4 IP SLA"}</h4>{"\n                    "}<p>{"\n                        ネットワークの"}<strong>{"品質を能動的に測定"}</strong>{"する機能です（ICMP\n                        Echo、UDP Jitter、TCP Connect、HTTP など）。結果を\n                        "}<strong>{"track"}</strong>{"\n                        と連携すると、障害時のスタティックルート切替・PBR・FHRP 制御に使えます。\n                    "}</p>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"ip"}</span>{" sla 10"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"icmp-echo"}</span>{" "}<span className={"t-n"}>{"198.51.100.1"}</span>{" source-interface GigabitEthernet0/0/0"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"frequency"}</span>{" 10"}</div><div className="code-line"><span className={"t-kw"}>{"ip"}</span>{" sla schedule 10 life forever start-time now"}</div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"track"}</span>{" 1 ip sla 10 reachability"}</div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"ip"}</span>{" route "}<span className={"t-n"}>{"0.0.0.0"}</span>{" "}<span className={"t-n"}>{"0.0.0.0"}</span>{" "}<span className={"t-n"}>{"198.51.100.1"}</span>{" track 1"}</div><div className="code-line"><span className={"t-kw"}>{"ip"}</span>{" route "}<span className={"t-n"}>{"0.0.0.0"}</span>{" "}<span className={"t-n"}>{"0.0.0.0"}</span>{" "}<span className={"t-n"}>{"203.0.113.1"}</span>{" 250     "}<span className={"t-cm"}>{"! フローティングスタティック"}</span></div></div>{"\n                    "}</div>{"\n                    "}<p>{"確認: "}<code>{"show ip sla statistics"}</code>{"、"}<code>{"show track"}</code></p>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                測定は「"}<strong>{"アプリの実際の宛先に近い"}</strong>{"」ターゲットを選ぶ（ゲートウェイの応答だけでは上流障害を検知できない）。頻度は短すぎると負荷になるので、要件に合わせて調整する。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h4 id={"45-cisco-catalyst-center旧-cisco-dna-center"}>{"\n                        4.5 Cisco Catalyst Center（旧 Cisco DNA Center）\n                    "}</h4>{"\n                    "}<p>{"\n                        Catalyst Center\n                        は"}<strong>{"設計（Design）／ポリシー（Policy）／プロビジョニング（Provision）／アシュアランス（Assurance）"}</strong>{"を一元的に扱う管理・自動化基盤です。試験内容では、"}<strong>{"従来型ワークフロー"}</strong>{"と\n                        "}<strong>{"AI 活用ワークフロー"}</strong>{"の両方での利用が問われます。\n                    "}</p>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"4.5 Cisco Catalyst Center（旧 Cisco DNA Center）（表 34）"}><thead><tr><th scope="col">{"機能"}{" "}</th><th scope="col">{"内容"}{" "}</th></tr></thead><tbody><tr><td>{"設計"}{" "}</td><td>{"\n                                        サイト階層、共通サービス（NTP/DNS/AAA）、ネットワーク設定の標準化\n                                    "}{" "}</td></tr><tr><td>{"ポリシー"}{" "}</td><td>{"\n                                        SD-Access の VN／SGT、アプリケーションポリシー（QoS）の定義\n                                    "}{" "}</td></tr><tr><td>{"プロビジョニング"}{" "}</td><td>{"テンプレートを使った設定配布、PnP によるゼロタッチ導入"}{" "}</td></tr><tr><td>{"アシュアランス"}{" "}</td><td>{"\n                                        有線／無線／アプリケーションの健全性スコア、問題の"}<strong>{"相関・根本原因分析"}</strong>{"\n                                    "}{" "}</td></tr><tr><td>{"SWIM"}{" "}</td><td>{"ソフトウェアイメージ管理（更新の標準化）"}{" "}</td></tr><tr><td>{"API / Webhook"}{" "}</td><td>{"Intent API による外部連携、イベント通知"}{" "}</td></tr><tr><td>{"AI 活用"}{" "}</td><td>{"\n                                        過去データに基づく異常検知、予測的な洞察、AI\n                                        拡張された無線最適化（RRM）など\n                                    "}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<Diagram id="dg15" label={"4.5 Cisco Catalyst Center（旧 Cisco DNA Center）"} />{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<ol>{"\n                                "}<li>{"\n                                    まず"}<strong>{"サイト階層と共通サービスの標準化"}</strong>{"から始める（後のテンプレートが効く）。\n                                "}</li>{"\n                                "}<li>{"\n                                    設定変更は"}<strong>{"テンプレート化して Catalyst Center 経由"}</strong>{"で行い、CLI 直接変更（ドリフト）を減らす。\n                                "}</li>{"\n                                "}<li>{"\n                                    アシュアランスで"}<strong>{"ベースライン"}</strong>{"を把握し、しきい値を運用に合わせて調整する。\n                                "}</li>{"\n                                "}<li>{"\n                                    外部システム連携は\n                                    "}<strong>{"Intent API と Webhook"}</strong>{"\n                                    を使い、手作業のチケット起票などを自動化する。\n                                "}</li>{"\n                            "}</ol>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h4 id={"46-netconf-と-restconf"}>{"4.6 NETCONF と RESTCONF"}</h4>{"\n                    "}<p>{"\n                        どちらも\n                        "}<strong>{"YANG モデルに基づく"}</strong>{"構造化データで機器を管理するプロトコルです（モデル＝YANG、プロトコル＝NETCONF/RESTCONF、符号化＝XML/JSON\n                        の 3 つを分けて考えるのがコツ）。\n                    "}</p>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"4.6 NETCONF と RESTCONF（表 35）"}><thead><tr><th scope="col">{"項目"}{" "}</th><th scope="col">{"NETCONF（RFC 6241）"}{" "}</th><th scope="col">{"RESTCONF（RFC 8040）"}{" "}</th></tr></thead><tbody><tr><td>{"トランスポート"}{" "}</td><td><strong>{"SSH"}</strong>{"（TCP 830）"}{" "}</td><td><strong>{"HTTPS"}</strong>{" "}</td></tr><tr><td>{"符号化"}{" "}</td><td>{"XML"}{" "}</td><td>{"JSON または XML"}{" "}</td></tr><tr><td>{"操作"}{" "}</td><td>{"\n                                        "}<code>{"<get>"}</code>{"、"}<code>{"<get-config>"}</code>{"、"}<code>{"<edit-config>"}</code>{"、"}<code>{"<commit>"}</code>{"\n                                        など RPC\n                                    "}{" "}</td><td>{"HTTP メソッド（GET/POST/PUT/PATCH/DELETE）"}{" "}</td></tr><tr><td>{"特徴"}{" "}</td><td>{"\n                                        データストア（running/candidate）やトランザクションに強い\n                                    "}{" "}</td><td>{"REST に慣れた開発者が使いやすい"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-cm"}>{"! IOS XE での有効化例"}</span></div><div className="code-line"><span className={"t-kw"}>{"netconf-yang"}</span></div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"ip"}</span>{" http secure-server"}</div><div className="code-line"><span className={"t-kw"}>{"restconf"}</span></div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"aaa"}</span>{" new-model"}</div><div className="code-line"><span className={"t-kw"}>{"aaa"}</span>{" authentication login default local"}</div><div className="code-line"><span className={"t-kw"}>{"aaa"}</span>{" authorization exec default local"}</div><div className="code-line"><span className={"t-kw"}>{"username"}</span>{" api-user privilege 15 secret "}<span className={"t-ph"}>{"<PASSWORD>"}</span></div></div>{"\n                    "}</div>{"\n                    "}<p>{"\n                        確認: "}<code>{"show netconf-yang status"}</code>{"、"}<code>{"show platform software yang-management process"}</code>{"、RESTCONF は "}<code>{"curl"}</code>{" 等で "}<code>{"/restconf/data"}</code>{" に GET\n                    "}</p>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                API\n                                専用の"}<strong>{"最小権限アカウント"}</strong>{"を作り、アクセス元を制限する。設定変更は"}<strong>{"トランザクション（NETCONF）"}</strong>{"の性質を活かし、事前に候補をレビューしてからコミットする。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                "}</section>
<section className={"sec sub"} id={"25-セキュリティ20"}>{"\n                    "}<h3 id={"25-セキュリティ20"}>{"2.5 セキュリティ（20%）"}</h3>{"\n                    "}<h4 id={"51-デバイスアクセス制御"}>{"5.1 デバイスアクセス制御"}</h4>{"\n                    "}<h5 id={"51a-回線とローカルユーザー認証"}>{"5.1.a 回線とローカルユーザー認証"}</h5>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"service"}</span>{" password-encryption"}</div><div className="code-line"><span className={"t-kw"}>{"enable"}</span>{" secret "}<span className={"t-ph"}>{"<STRONG-SECRET>"}</span></div><div className="code-line"><span className={"t-kw"}>{"username"}</span>{" admin privilege 15 algorithm-type scrypt secret "}<span className={"t-ph"}>{"<PASSWORD>"}</span></div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"ip"}</span>{" domain-name example.local"}</div><div className="code-line"><span className={"t-kw"}>{"crypto"}</span>{" key generate rsa modulus 3072"}</div><div className="code-line"><span className={"t-kw"}>{"ip"}</span>{" ssh version 2"}</div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"line"}</span>{" console 0"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"login"}</span>{" local"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"exec-timeout"}</span>{" 5 0"}</div><div className="code-line"><span className={"t-kw"}>{"line"}</span>{" vty 0 15"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"login"}</span>{" local"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"transport"}</span>{" input ssh"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"access-class"}</span>{" MGMT-ONLY in"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"exec-timeout"}</span>{" 5 0"}</div></div>{"\n                    "}</div>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<ol>{"\n                                "}<li>{"\n                                    "}<strong>{"Telnet を無効化し SSH v2 のみ"}</strong>{"（"}<code>{"transport input ssh"}</code>{"）。\n                                "}</li>{"\n                                "}<li>{"\n                                    パスワードは "}<code>{"enable secret"}</code>{"／"}<code>{"secret"}</code>{"\n                                    を使い、"}<strong>{"タイプ 0（平文）や弱い暗号化を避ける"}</strong>{"。\n                                "}</li>{"\n                                "}<li>{"\n                                    VTY には\n                                    "}<strong>{"ACL（"}<code>{"access-class"}</code>{"）で管理元を限定"}</strong>{"し、アイドルタイムアウトを設定する。\n                                "}</li>{"\n                                "}<li>{"\n                                    ローカルユーザーは緊急用（ブレークグラス）に限定し、日常運用は\n                                    AAA（集中認証）を使う。\n                                "}</li>{"\n                            "}</ol>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h5 id={"51b-aaa-による認証と認可"}>{"5.1.b AAA による認証と認可"}</h5>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"5.1 デバイスアクセス制御（表 36）"}><thead><tr><th scope="col">{"機能"}{" "}</th><th scope="col">{"意味"}{" "}</th></tr></thead><tbody><tr><td>{"Authentication（認証）"}{" "}</td><td>{"「誰か」を確認"}{" "}</td></tr><tr><td>{"Authorization（認可）"}{" "}</td><td>{"「何ができるか」を決定"}{" "}</td></tr><tr><td>{"Accounting（アカウンティング）"}{" "}</td><td>{"「何をしたか」を記録"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"5.1 デバイスアクセス制御（表 37）"}><thead><tr><th scope="col">{"項目"}{" "}</th><th scope="col">{"TACACS+"}{" "}</th><th scope="col">{"RADIUS"}{" "}</th></tr></thead><tbody><tr><td>{"トランスポート"}{" "}</td><td>{"TCP 49"}{" "}</td><td>{"UDP 1812（認証）/1813（アカウンティング）"}{" "}</td></tr><tr><td>{"暗号化"}{" "}</td><td><strong>{"パケット本体全体"}</strong>{" "}</td><td>{"パスワードのみ"}{" "}</td></tr><tr><td>{"AAA の分離"}{" "}</td><td>{"認証・認可・アカウンティングを"}<strong>{"分離可能"}</strong>{" "}</td><td>{"認証と認可が結合しやすい"}{" "}</td></tr><tr><td>{"主な用途"}{" "}</td><td><strong>{"デバイス管理"}</strong>{"（コマンド認可）"}{" "}</td><td><strong>{"ネットワークアクセス"}</strong>{"（802.1X、VPN）"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"aaa"}</span>{" new-model"}</div><div className="code-line"><span className={"t-kw"}>{"tacacs"}</span>{" server TAC-1"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"address"}</span>{" ipv4 "}<span className={"t-n"}>{"192.0.2.10"}</span></div><div className="code-line">{" "}<span className={"t-sub"}>{"key"}</span>{" "}<span className={"t-ph"}>{"<SHARED-KEY>"}</span></div><div className="code-line"><span className={"t-kw"}>{"aaa"}</span>{" group server tacacs+ TAC-GRP"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"server"}</span>{" name TAC-1"}</div><div className="code-line"><span className={"t-kw"}>{"aaa"}</span>{" authentication login default group TAC-GRP local"}</div><div className="code-line"><span className={"t-kw"}>{"aaa"}</span>{" authorization exec default group TAC-GRP local"}</div><div className="code-line"><span className={"t-kw"}>{"aaa"}</span>{" accounting commands 15 default start-stop group TAC-GRP"}</div></div>{"\n                    "}</div>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                リスト末尾に\n                                "}<strong><code>{"local"}</code>{" をフォールバック"}</strong>{"として置き、AAA\n                                サーバー障害でも入れるようにする（ロックアウト防止）。"}<strong>{"設定変更前に別セッションを開いたまま"}</strong>{"テストする。デバイス管理は\n                                TACACS+、端末認証は RADIUS（ISE 等）と使い分ける。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h4 id={"52-インフラストラクチャのセキュリティ機能"}>{"\n                        5.2 インフラストラクチャのセキュリティ機能\n                    "}</h4>{"\n                    "}<h5 id={"52a-acl"}>{"5.2.a ACL"}</h5>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"5.2 インフラストラクチャのセキュリティ機能（表 38）"}><thead><tr><th scope="col">{"種類"}{" "}</th><th scope="col">{"判定項目"}{" "}</th><th scope="col">{"配置の目安"}{" "}</th></tr></thead><tbody><tr><td>{"標準 ACL"}{" "}</td><td>{"送信元 IP のみ"}{" "}</td><td><strong>{"宛先に近い"}</strong>{"位置"}{" "}</td></tr><tr><td>{"拡張 ACL"}{" "}</td><td>{"送信元・宛先 IP、プロトコル、ポート"}{" "}</td><td><strong>{"送信元に近い"}</strong>{"位置"}{" "}</td></tr><tr><td>{"名前付き ACL"}{" "}</td><td>{"名前で管理（編集しやすい）"}{" "}</td><td>{"推奨"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"ip"}</span>{" access-list extended MGMT-ONLY"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"permit"}</span>{" tcp "}<span className={"t-n"}>{"192.0.2.0"}</span>{" "}<span className={"t-n"}>{"0.0.0.255"}</span>{" any eq 22"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"deny"}</span>{"   ip any any log"}</div></div>{"\n                    "}</div>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<ol>{"\n                                "}<li>{"\n                                    ACL の末尾には"}<strong>{"暗黙の deny"}</strong>{" がある（明示的な\n                                    "}<code>{"deny ip any any log"}</code>{" で可視化するのが有用）。\n                                "}</li>{"\n                                "}<li>{"\n                                    "}<strong>{"具体的なルールを上に"}</strong>{"、汎用ルールを下に（上から順に評価され、最初に一致した時点で終了）。\n                                "}</li>{"\n                                "}<li>{"\n                                    名前付き ACL とシーケンス番号を使い、変更時は"}<strong>{"新 ACL を作って差し替え"}</strong>{"る。\n                                "}</li>{"\n                                "}<li>{"適用方向（in/out）を必ず確認する。"}</li>{"\n                            "}</ol>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h5 id={"52b-coppcontrol-plane-policing"}>{"\n                        5.2.b CoPP（Control Plane Policing）\n                    "}</h5>{"\n                    "}<p>{"\n                        ルータ／スイッチの"}<strong>{"制御プレーン（CPU 宛の通信）"}</strong>{"を QoS\n                        の仕組み（MQC）で制限し、DoS\n                        や過剰なトラフィックから制御プレーンを守ります。\n                    "}</p>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"class-map"}</span>{" match-all COPP-ROUTING"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"match"}</span>{" access-group name ACL-ROUTING"}</div><div className="code-line"><span className={"t-kw"}>{"class-map"}</span>{" match-all COPP-MGMT"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"match"}</span>{" access-group name ACL-MGMT"}</div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"policy-map"}</span>{" COPP-POLICY"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"class"}</span>{" COPP-ROUTING"}</div><div className="code-line">{"  "}<span className={"t-sub"}>{"police"}</span>{" rate 1000 pps conform-action transmit exceed-action transmit"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"class"}</span>{" COPP-MGMT"}</div><div className="code-line">{"  "}<span className={"t-sub"}>{"police"}</span>{" rate 200 pps conform-action transmit exceed-action drop"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"class"}</span>{" class-default"}</div><div className="code-line">{"  "}<span className={"t-sub"}>{"police"}</span>{" rate 100 pps conform-action transmit exceed-action drop"}</div><div className="code-line"><span className={"t-cm"}>{"!"}</span></div><div className="code-line"><span className={"t-kw"}>{"control-plane"}</span></div><div className="code-line">{" "}<span className={"t-sub"}>{"service-policy"}</span>{" input COPP-POLICY"}</div></div>{"\n                    "}</div>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                いきなり drop せず、"}<strong>{"まず transmit（観測モード）で\n                                    "}<code>{"show policy-map control-plane"}</code>{"\n                                    のカウンタを確認"}</strong>{"してから、実測に基づく値で制限する。ルーティングプロトコルのクラスを誤って絞らないよう注意する。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h4 id={"53-rest-api-セキュリティ"}>{"5.3 REST API セキュリティ"}</h4>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"5.3 REST API セキュリティ（表 39）"}><thead><tr><th scope="col">{"対策"}{" "}</th><th scope="col">{"内容"}{" "}</th></tr></thead><tbody><tr><td>{"通信の保護"}{" "}</td><td>{"\n                                        "}<strong>{"HTTPS（TLS）必須"}</strong>{"。証明書を検証する（"}<code>{"verify=False"}</code>{"\n                                        は検証環境のみ）\n                                    "}{" "}</td></tr><tr><td>{"認証"}{" "}</td><td>{"\n                                        トークン（Bearer）、OAuth 2.0、API キー、クライアント証明書\n                                    "}{" "}</td></tr><tr><td>{"認可"}{" "}</td><td><strong>{"最小権限"}</strong>{"（RBAC）、スコープ制限"}{" "}</td></tr><tr><td>{"秘密情報"}{" "}</td><td>{"\n                                        トークン・パスワードを"}<strong>{"コードに埋め込まない"}</strong>{"（環境変数・シークレット管理）\n                                    "}{" "}</td></tr><tr><td>{"入力検証"}{" "}</td><td>{"不正なペイロードを拒否（インジェクション対策）"}{" "}</td></tr><tr><td>{"濫用対策"}{" "}</td><td>{"レート制限、監査ログ、トークンの有効期限"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                トークンは短命にし、ログに出力しない。APIの利用元を IP\n                                制限し、変更系（POST/PUT/DELETE）は監査ログで追跡できるようにする。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h4 id={"54-ネットワークセキュリティ設計の要素"}>{"\n                        5.4 ネットワークセキュリティ設計の要素\n                    "}</h4>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"5.4 ネットワークセキュリティ設計の要素（表 40）"}><thead><tr><th scope="col">{"要素"}{" "}</th><th scope="col">{"役割"}{" "}</th></tr></thead><tbody><tr><td>{"脅威防御"}{" "}</td><td>{"\n                                        IPS、マルウェア対策、脅威インテリジェンスによる検知・遮断\n                                    "}{" "}</td></tr><tr><td>{"エンドポイントセキュリティ"}{" "}</td><td>{"端末の可視化・保護・隔離（EDR、姿勢評価）"}{" "}</td></tr><tr><td>{"次世代ファイアウォール（NGFW）"}{" "}</td><td>{"\n                                        アプリケーション識別、IPS、URL\n                                        フィルタ、マルウェア対策を統合\n                                    "}{" "}</td></tr><tr><td><strong>{"TrustSec"}</strong>{" "}</td><td>{"\n                                        通信を\n                                        "}<strong>{"SGT（Security Group Tag）"}</strong>{"で分類し、"}<strong>{"SGACL"}</strong>{"\n                                        でグループ間のアクセスを制御\n                                    "}{" "}</td></tr><tr><td><strong>{"MACsec（IEEE 802.1AE）"}</strong>{" "}</td><td>{"\n                                        "}<strong>{"イーサネットリンク（L2 ホップごと）を暗号化"}</strong>{"（鍵交換は MKA）\n                                    "}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<Diagram id="dg16" label={"5.4 ネットワークセキュリティ設計の要素"} />{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<ol>{"\n                                "}<li>{"\n                                    "}<strong>{"ゼロトラストの考え方"}</strong>{"：ネットワークの位置ではなく、"}<strong>{"ID・端末状態"}</strong>{"に基づいてアクセスを制御する。\n                                "}</li>{"\n                                "}<li>{"\n                                    セグメンテーションは、まず大きな単位（VRF/VN）→\n                                    次にグループ単位（SGT）の順で段階導入する。\n                                "}</li>{"\n                                "}<li>{"\n                                    MACsec\n                                    は"}<strong>{"リンク単位"}</strong>{"の暗号化である点に注意（エンドツーエンドではない）。エンドツーエンド保護は\n                                    IPsec/TLS と組み合わせる。\n                                "}</li>{"\n                            "}</ol>{"\n                        "}</div>{"\n                    "}</aside>{"\n                "}</section>
<section className={"sec sub"} id={"26-自動化と人工知能15"}>{"\n                    "}<h3 id={"26-自動化と人工知能15"}>{"2.6 自動化と人工知能（15%）"}</h3>{"\n                    "}<p>{"\n                        "}<strong>{"なぜ必要か"}</strong>{":\n                        手作業は遅く、ミスが起きます。"}<strong>{"コード（設定・テンプレート・スクリプト）でネットワークを管理する"}</strong>{"と、再現性・監査性・スピードが上がります。\n                    "}</p>{"\n                    "}<h4 id={"61-基本的な-python-コンポーネントとスクリプト"}>{"\n                        6.1 基本的な Python コンポーネントとスクリプト\n                    "}</h4>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"6.1 基本的な Python コンポーネントとスクリプト（表 41）"}><thead><tr><th scope="col">{"要素"}{" "}</th><th scope="col">{"例"}{" "}</th></tr></thead><tbody><tr><td>{"データ型"}{" "}</td><td>{"\n                                        "}<code>{"str"}</code>{"、"}<code>{"int"}</code>{"、"}<code>{"bool"}</code>{"、"}<code>{"list"}</code>{"、"}<code>{"dict"}</code>{"\n                                    "}{" "}</td></tr><tr><td>{"制御構文"}{" "}</td><td><code>{"if"}</code>{"、"}<code>{"for"}</code>{"、"}<code>{"while"}</code>{" "}</td></tr><tr><td>{"関数"}{" "}</td><td><code>{"def"}</code>{" "}</td></tr><tr><td>{"ライブラリ"}{" "}</td><td>{"\n                                        "}<code>{"requests"}</code>{"（HTTP）、"}<code>{"json"}</code>{"、"}<code>{"netmiko"}</code>{"、"}<code>{"ncclient"}</code>{"\n                                    "}{" "}</td></tr><tr><td>{"例外処理"}{" "}</td><td><code>{"try / except"}</code>{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"Python"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"Python（コードブロック）"}><div className="code-line"><span className={"kn"}>{"import"}</span><span className={"w"}>{" "}</span><span className={"nn"}>{"requests"}</span></div><div className="code-line">{""}</div><div className="code-line"><span className={"n"}>{"requests"}</span><span className={"o"}>{"."}</span><span className={"n"}>{"packages"}</span><span className={"o"}>{"."}</span><span className={"n"}>{"urllib3"}</span><span className={"o"}>{"."}</span><span className={"n"}>{"disable_warnings"}</span><span className={"p"}>{"()"}</span>{"  "}<span className={"c1"}>{"# 検証環境のみ。本番では証明書を検証する"}</span></div><div className="code-line">{""}</div><div className="code-line"><span className={"n"}>{"url"}</span>{" "}<span className={"o"}>{"="}</span>{" "}<span className={"s2"}>{"\"https://192.0.2.10/restconf/data/ietf-interfaces:interfaces\""}</span></div><div className="code-line"><span className={"n"}>{"headers"}</span>{" "}<span className={"o"}>{"="}</span>{" "}<span className={"p"}>{"{"}</span><span className={"s2"}>{"\"Accept\""}</span><span className={"p"}>{":"}</span>{" "}<span className={"s2"}>{"\"application/yang-data+json\""}</span><span className={"p"}>{"}"}</span></div><div className="code-line">{""}</div><div className="code-line"><span className={"n"}>{"resp"}</span>{" "}<span className={"o"}>{"="}</span>{" "}<span className={"n"}>{"requests"}</span><span className={"o"}>{"."}</span><span className={"n"}>{"get"}</span><span className={"p"}>{"("}</span><span className={"n"}>{"url"}</span><span className={"p"}>{","}</span>{" "}<span className={"n"}>{"headers"}</span><span className={"o"}>{"="}</span><span className={"n"}>{"headers"}</span><span className={"p"}>{","}</span></div><div className="code-line">{"                    "}<span className={"n"}>{"auth"}</span><span className={"o"}>{"="}</span><span className={"p"}>{"("}</span><span className={"s2"}>{"\"api-user\""}</span><span className={"p"}>{","}</span>{" "}<span className={"s2"}>{"\"<PASSWORD>\""}</span><span className={"p"}>{"),"}</span>{" "}<span className={"n"}>{"verify"}</span><span className={"o"}>{"="}</span><span className={"kc"}>{"False"}</span><span className={"p"}>{","}</span>{" "}<span className={"n"}>{"timeout"}</span><span className={"o"}>{"="}</span><span className={"mi"}>{"10"}</span><span className={"p"}>{")"}</span></div><div className="code-line"><span className={"n"}>{"resp"}</span><span className={"o"}>{"."}</span><span className={"n"}>{"raise_for_status"}</span><span className={"p"}>{"()"}</span></div><div className="code-line">{""}</div><div className="code-line"><span className={"k"}>{"for"}</span>{" "}<span className={"n"}>{"intf"}</span>{" "}<span className={"ow"}>{"in"}</span>{" "}<span className={"n"}>{"resp"}</span><span className={"o"}>{"."}</span><span className={"n"}>{"json"}</span><span className={"p"}>{"()["}</span><span className={"s2"}>{"\"ietf-interfaces:interfaces\""}</span><span className={"p"}>{"]["}</span><span className={"s2"}>{"\"interface\""}</span><span className={"p"}>{"]:"}</span></div><div className="code-line">{"    "}<span className={"nb"}>{"print"}</span><span className={"p"}>{"("}</span><span className={"n"}>{"intf"}</span><span className={"p"}>{"["}</span><span className={"s2"}>{"\"name\""}</span><span className={"p"}>{"],"}</span>{" "}<span className={"n"}>{"intf"}</span><span className={"o"}>{"."}</span><span className={"n"}>{"get"}</span><span className={"p"}>{"("}</span><span className={"s2"}>{"\"enabled\""}</span><span className={"p"}>{"))"}</span></div></div>{"\n                    "}</div>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                仮想環境（venv）で依存関係を分離する。認証情報はコードに書かず環境変数等から読む。"}<strong>{"タイムアウトと例外処理"}</strong>{"を必ず入れる。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h4 id={"62-有効な-json-エンコードファイルの作成"}>{"\n                        6.2 有効な JSON エンコードファイルの作成\n                    "}</h4>{"\n                    "}<p>{"\n                        JSON のルール:\n                        キーは"}<strong>{"ダブルクォート"}</strong>{"、末尾カンマ禁止、コメント不可、値は文字列・数値・真偽値・null・配列・オブジェクト。\n                    "}</p>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"JSON"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"JSON（コードブロック）"}><div className="code-line"><span className={"p"}>{"{"}</span></div><div className="code-line"><span className={"w"}>{"  "}</span><span className={"nt"}>{"\"ietf-interfaces:interface\""}</span><span className={"p"}>{":"}</span><span className={"w"}>{" "}</span><span className={"p"}>{"{"}</span></div><div className="code-line"><span className={"w"}>{"    "}</span><span className={"nt"}>{"\"name\""}</span><span className={"p"}>{":"}</span><span className={"w"}>{" "}</span><span className={"s2"}>{"\"Loopback100\""}</span><span className={"p"}>{","}</span></div><div className="code-line"><span className={"w"}>{"    "}</span><span className={"nt"}>{"\"description\""}</span><span className={"p"}>{":"}</span><span className={"w"}>{" "}</span><span className={"s2"}>{"\"Created by RESTCONF\""}</span><span className={"p"}>{","}</span></div><div className="code-line"><span className={"w"}>{"    "}</span><span className={"nt"}>{"\"type\""}</span><span className={"p"}>{":"}</span><span className={"w"}>{" "}</span><span className={"s2"}>{"\"iana-if-type:softwareLoopback\""}</span><span className={"p"}>{","}</span></div><div className="code-line"><span className={"w"}>{"    "}</span><span className={"nt"}>{"\"enabled\""}</span><span className={"p"}>{":"}</span><span className={"w"}>{" "}</span><span className={"kc"}>{"true"}</span><span className={"p"}>{","}</span></div><div className="code-line"><span className={"w"}>{"    "}</span><span className={"nt"}>{"\"ietf-ip:ipv4\""}</span><span className={"p"}>{":"}</span><span className={"w"}>{" "}</span><span className={"p"}>{"{"}</span></div><div className="code-line"><span className={"w"}>{"      "}</span><span className={"nt"}>{"\"address\""}</span><span className={"p"}>{":"}</span><span className={"w"}>{" "}</span><span className={"p"}>{"["}</span></div><div className="code-line"><span className={"w"}>{"        "}</span><span className={"p"}>{"{"}</span><span className={"w"}>{" "}</span><span className={"nt"}>{"\"ip\""}</span><span className={"p"}>{":"}</span><span className={"w"}>{" "}</span><span className={"s2"}>{"\"10.100.0.1\""}</span><span className={"p"}>{","}</span><span className={"w"}>{" "}</span><span className={"nt"}>{"\"netmask\""}</span><span className={"p"}>{":"}</span><span className={"w"}>{" "}</span><span className={"s2"}>{"\"255.255.255.255\""}</span><span className={"w"}>{" "}</span><span className={"p"}>{"}"}</span></div><div className="code-line"><span className={"w"}>{"      "}</span><span className={"p"}>{"]"}</span></div><div className="code-line"><span className={"w"}>{"    "}</span><span className={"p"}>{"}"}</span></div><div className="code-line"><span className={"w"}>{"  "}</span><span className={"p"}>{"}"}</span></div><div className="code-line"><span className={"p"}>{"}"}</span></div></div>{"\n                    "}</div>{"\n                    "}<aside className={"callout note"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-info-circle"}></i><span>{"よくあるミス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                シングルクォート、末尾カンマ、"}<code>{"True"}</code>{"（Python 表記）を\n                                JSON の "}<code>{"true"}</code>{" と混同する。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h4 id={"63-yang-などのデータモデリング言語"}>{"\n                        6.3 YANG などのデータモデリング言語\n                    "}</h4>{"\n                    "}<p>{"\n                        "}<strong>{"YANG（RFC 7950）"}</strong>{"\n                        は、設定データ・状態データ・RPC・通知の"}<strong>{"構造と制約を定義するモデリング言語"}</strong>{"です。\n                    "}</p>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"6.3 YANG などのデータモデリング言語（表 42）"}><thead><tr><th scope="col">{"モデル種別"}{" "}</th><th scope="col">{"特徴"}{" "}</th></tr></thead><tbody><tr><td>{"IETF"}{" "}</td><td>{"標準化。ベンダー共通の基本機能"}{" "}</td></tr><tr><td>{"OpenConfig"}{" "}</td><td>{"事業者主導のベンダー中立モデル"}{" "}</td></tr><tr><td>{"Cisco ネイティブ"}{" "}</td><td>{"Cisco 固有機能をカバー（IOS XE の機能を最も網羅）"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<p>{"\n                        利点:\n                        型・範囲チェック、ベンダー間の共通化、ツールでの自動生成、"}<strong>{"トランザクション的な設定"}</strong>{"。モジュール構造は\n                        "}<code>{"pyang -f tree"}</code>{" などで\n                        "}<strong>{"ツリー表示（RFC 8340）"}</strong>{" して確認できます。\n                    "}</p>{"\n                    "}<h4 id={"64-catalyst-center-と-sd-wan-manager-の-api"}>{"\n                        6.4 Catalyst Center と SD-WAN Manager の API\n                    "}</h4>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"6.4 Catalyst Center と SD-WAN Manager の API（表 43）"}><thead><tr><th scope="col">{"項目"}{" "}</th><th scope="col">{"Catalyst Center"}{" "}</th><th scope="col">{"SD-WAN Manager"}{" "}</th></tr></thead><tbody><tr><td>{"認証"}{" "}</td><td>{"\n                                        認証エンドポイントでトークン取得（"}<code>{"X-Auth-Token"}</code>{"\n                                        ヘッダを付与）\n                                    "}{" "}</td><td>{"\n                                        バージョンによりセッション／トークン方式が異なる（公式ドキュメントで確認）\n                                    "}{" "}</td></tr><tr><td>{"主な API"}{" "}</td><td>{"\n                                        "}<strong>{"Intent API"}</strong>{"（デバイス、サイト、テンプレート、SDA\n                                        等）、イベント/Webhook\n                                    "}{" "}</td><td>{"デバイスインベントリ、モニタリング、設定、管理系"}{" "}</td></tr><tr><td>{"形式"}{" "}</td><td>{"REST（HTTPS + JSON）"}{" "}</td><td>{"REST（HTTPS + JSON）"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"Python"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"Python（コードブロック）"}><div className="code-line"><span className={"c1"}>{"# Catalyst Center: トークン取得 → デバイス一覧"}</span></div><div className="code-line"><span className={"kn"}>{"import"}</span><span className={"w"}>{" "}</span><span className={"nn"}>{"requests"}</span></div><div className="code-line"><span className={"n"}>{"base"}</span>{" "}<span className={"o"}>{"="}</span>{" "}<span className={"s2"}>{"\"https://catalyst.example.local\""}</span></div><div className="code-line"><span className={"n"}>{"tok"}</span>{" "}<span className={"o"}>{"="}</span>{" "}<span className={"n"}>{"requests"}</span><span className={"o"}>{"."}</span><span className={"n"}>{"post"}</span><span className={"p"}>{"("}</span><span className={"sa"}>{"f"}</span><span className={"s2"}>{"\""}</span><span className={"si"}>{"{"}</span><span className={"n"}>{"base"}</span><span className={"si"}>{"}"}</span><span className={"s2"}>{"/dna/system/api/v1/auth/token\""}</span><span className={"p"}>{","}</span></div><div className="code-line">{"                    "}<span className={"n"}>{"auth"}</span><span className={"o"}>{"="}</span><span className={"p"}>{"("}</span><span className={"s2"}>{"\"api-user\""}</span><span className={"p"}>{","}</span>{" "}<span className={"s2"}>{"\"<PASSWORD>\""}</span><span className={"p"}>{"),"}</span>{" "}<span className={"n"}>{"verify"}</span><span className={"o"}>{"="}</span><span className={"kc"}>{"False"}</span><span className={"p"}>{")"}</span><span className={"o"}>{"."}</span><span className={"n"}>{"json"}</span><span className={"p"}>{"()["}</span><span className={"s2"}>{"\"Token\""}</span><span className={"p"}>{"]"}</span></div><div className="code-line"><span className={"n"}>{"devs"}</span>{" "}<span className={"o"}>{"="}</span>{" "}<span className={"n"}>{"requests"}</span><span className={"o"}>{"."}</span><span className={"n"}>{"get"}</span><span className={"p"}>{"("}</span><span className={"sa"}>{"f"}</span><span className={"s2"}>{"\""}</span><span className={"si"}>{"{"}</span><span className={"n"}>{"base"}</span><span className={"si"}>{"}"}</span><span className={"s2"}>{"/dna/intent/api/v1/network-device\""}</span><span className={"p"}>{","}</span></div><div className="code-line">{"                    "}<span className={"n"}>{"headers"}</span><span className={"o"}>{"="}</span><span className={"p"}>{"{"}</span><span className={"s2"}>{"\"X-Auth-Token\""}</span><span className={"p"}>{":"}</span>{" "}<span className={"n"}>{"tok"}</span><span className={"p"}>{"},"}</span>{" "}<span className={"n"}>{"verify"}</span><span className={"o"}>{"="}</span><span className={"kc"}>{"False"}</span><span className={"p"}>{")"}</span><span className={"o"}>{"."}</span><span className={"n"}>{"json"}</span><span className={"p"}>{"()["}</span><span className={"s2"}>{"\"response\""}</span><span className={"p"}>{"]"}</span></div><div className="code-line"><span className={"nb"}>{"print"}</span><span className={"p"}>{"(["}</span><span className={"n"}>{"d"}</span><span className={"p"}>{"["}</span><span className={"s2"}>{"\"hostname\""}</span><span className={"p"}>{"]"}</span>{" "}<span className={"k"}>{"for"}</span>{" "}<span className={"n"}>{"d"}</span>{" "}<span className={"ow"}>{"in"}</span>{" "}<span className={"n"}>{"devs"}</span><span className={"p"}>{"])"}</span></div></div>{"\n                    "}</div>{"\n                    "}<h4 id={"65-rest-api-応答コードとペイロード"}>{"\n                        6.5 REST API 応答コードとペイロード\n                    "}</h4>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"6.5 REST API 応答コードとペイロード（表 44）"}><thead><tr><th scope="col">{"コード"}{" "}</th><th scope="col">{"意味"}{" "}</th><th scope="col">{"よくある原因／対処"}{" "}</th></tr></thead><tbody><tr><td>{"200 OK"}{" "}</td><td>{"成功（取得・更新）"}{" "}</td><td>{"—"}{" "}</td></tr><tr><td>{"201 Created"}{" "}</td><td>{"作成成功"}{" "}</td><td>{"—"}{" "}</td></tr><tr><td>{"204 No Content"}{" "}</td><td>{"成功（本文なし）"}{" "}</td><td>{"RESTCONF の更新・削除で一般的"}{" "}</td></tr><tr><td>{"400 Bad Request"}{" "}</td><td>{"要求形式が不正"}{" "}</td><td>{"JSON/XML 構文、必須項目の欠落"}{" "}</td></tr><tr><td>{"401 Unauthorized"}{" "}</td><td>{"認証失敗"}{" "}</td><td>{"資格情報・トークン期限"}{" "}</td></tr><tr><td>{"403 Forbidden"}{" "}</td><td>{"権限不足"}{" "}</td><td>{"RBAC・アクセス元制限"}{" "}</td></tr><tr><td>{"404 Not Found"}{" "}</td><td>{"対象が存在しない"}{" "}</td><td>{"URI・リソース名の誤り"}{" "}</td></tr><tr><td>{"409 Conflict"}{" "}</td><td>{"競合"}{" "}</td><td>{"既に存在するリソースの作成 など"}{" "}</td></tr><tr><td>{"429 Too Many Requests"}{" "}</td><td>{"レート制限"}{" "}</td><td>{"間隔を空けて再試行（バックオフ）"}{" "}</td></tr><tr><td>{"5xx"}{" "}</td><td>{"サーバー側エラー"}{" "}</td><td>{"装置／コントローラの状態を確認"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<Diagram id="dg17" label={"6.5 REST API 応答コードとペイロード"} />{"\n                    "}<h4 id={"66-eem-アプレット"}>{"6.6 EEM アプレット"}</h4>{"\n                    "}<p>{"\n                        "}<strong>{"EEM（Embedded Event Manager）"}</strong>{" は、"}<strong>{"イベント（ログ・タイマー・CLI 実行など）をトリガー"}</strong>{"に、機器内で自動処理を実行する仕組みです。\n                    "}</p>{"\n                    "}<div className={"codeblock"}>{"\n                        "}<div className={"code-label"}>{"IOS XE CLI / 設定例"}</div>{"\n                        "}<div className="code-block" tabIndex={0} role="region" aria-label={"IOS XE CLI / 設定例（コードブロック）"}><div className="code-line"><span className={"t-kw"}>{"event"}</span>{" manager applet LINK-DOWN-NOTIFY"}</div><div className="code-line">{" "}<span className={"t-sub"}>{"event"}</span>{" syslog pattern "}<span className={"t-s"}>{"\"%LINK-3-UPDOWN.*GigabitEthernet1/0/1.*down\""}</span></div><div className="code-line">{" "}<span className={"t-sub"}>{"action"}</span>{" 1.0 syslog msg "}<span className={"t-s"}>{"\"EEM: Gi1/0/1 down detected\""}</span></div><div className="code-line">{" "}<span className={"t-sub"}>{"action"}</span>{" 2.0 cli command "}<span className={"t-s"}>{"\"enable\""}</span></div><div className="code-line">{" "}<span className={"t-sub"}>{"action"}</span>{" 3.0 cli command "}<span className={"t-s"}>{"\"show interfaces GigabitEthernet1/0/1\""}</span></div><div className="code-line">{" "}<span className={"t-sub"}>{"action"}</span>{" 4.0 syslog msg "}<span className={"t-s"}>{"\"EEM: diagnostic collected\""}</span></div></div>{"\n                    "}</div>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                アプレットは"}<strong>{"小さく、冪等（何度実行しても安全）"}</strong>{"にする。破壊的な操作（reload、設定削除）は避け、動作は必ず検証環境でテストする。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                    "}<h4 id={"67-エージェント型とエージェントレス型のオーケストレーション"}>{"\n                        6.7 エージェント型とエージェントレス型のオーケストレーション\n                    "}</h4>{"\n                    "}<div className={"table-wrap"}>{"\n                        "}<table aria-label={"6.7 エージェント型とエージェントレス型のオーケストレーション（表 45）"}><thead><tr><th scope="col">{"項目"}{" "}</th><th scope="col">{"エージェント型"}{" "}</th><th scope="col">{"エージェントレス型"}{" "}</th></tr></thead><tbody><tr><td>{"例"}{" "}</td><td>{"Puppet、Chef"}{" "}</td><td>{"Ansible、Terraform"}{" "}</td></tr><tr><td>{"対象機器に常駐ソフト"}{" "}</td><td>{"必要"}{" "}</td><td><strong>{"不要"}</strong>{"（SSH / NETCONF / API で接続）"}{" "}</td></tr><tr><td>{"動作"}{" "}</td><td>{"\n                                        エージェントがサーバーへ"}<strong>{"プル"}</strong>{"して状態を収束\n                                    "}{" "}</td><td>{"実行時に制御ノードから"}<strong>{"プッシュ"}</strong>{" "}</td></tr><tr><td>{"ネットワーク機器との相性"}{" "}</td><td>{"対応機器が限られる"}{" "}</td><td>{"SSH/API 経由で広く適用可能"}{" "}</td></tr></tbody></table>{"\n                    "}</div>{"\n                    "}<aside className={"callout practice"}>{"\n                        "}<div className={"callout-head"}>{"\n                            "}<i aria-hidden={"true"} className={"ti ti-bulb"}></i><span>{"ベストプラクティス"}</span>{"\n                        "}</div>{"\n                        "}<div className={"callout-body"}>{"\n                            "}<p>{"\n                                構成は "}<strong>{"Git で管理"}</strong>{"（Infrastructure as\n                                Code）し、"}<strong>{"変更前にドライラン／差分確認"}</strong>{"（"}<code>{"--check"}</code>{"、"}<code>{"terraform plan"}</code>{"）を行う。\n                            "}</p>{"\n                        "}</div>{"\n                    "}</aside>{"\n                "}</section>
        </>
    );
}
